TAB_Describe[776] = {"#C(#8B6914)Mỗi ngày #C(#00962B)lần thứ 3#C(#8B6914) dùng Kim Cương, Vé Làm Mới làm mới sẽ nhận được nhiệm vụ Cam."}
TAB_Describe[777] = {"Anh hùng này đến từ Thứ Nguyên khác, tạm thời chưa có thông tin"}
TAB_Describe[778] = {"1. Lần đầu vượt Tháp Vô Tận có thể nhận thưởng Đá Tiến Bậc, mỗi 10 tầng nhận thêm 1 phần thưởng vượt ải\n\n2. Lần đầu khiêu chiến ở mỗi tầng không tốn lượt, tầng đã vượt có thể càn quét, mỗi ngày có 2 lượt càn quét miễn phí\n\n3. Lượt càn quét miễn phí làm mới lúc 00:00 mỗi ngày\n\n4. Có thể tốn Kim Cương mua lượt khiêu chiến, mỗi ngày giới hạn mua 3 lần"}
TAB_Describe[779] = {"1. Mỗi lần khiêu chiến Thủ Vệ trong PB đều sẽ nhận Cống Hiến Guild, Vàng\n\n2. Sau khi diệt Thủ Vệ sẽ dựa vào xếp hạng S.Thương tạo thành của thành viên Guild với Thủ Vệ này để phát thưởng, người diệt có thể nhận thêm thưởng diệt, đồng thời Guild sẽ nhận EXP Guild\n\n3. Mỗi ngày người chơi có 2 lượt khiêu chiến miễn phí, lượt cài lại vào 0h mỗi ngày, ngoài ra người chơi có thể tốn Kim Cương mua thêm lượt khiêu chiến\n\n4. Càn quét sẽ tiếp tục kế thừa lượng S.Thương lần khiêu chiến trước đó để tổng kết, càn quét tốn 1 lượt khiêu chiến\n\n5. Tốn Kim Cương có thể kích hoạt tăng hiệu quả tăng Buff công toàn Guild, tối đa có thể tăng đến 20% Buff lực công\n\n6. Mỗi phần thưởng diệt Thủ Vệ, thưởng xếp hạng một nhân vật chỉ được nhận 1 lần, đổi Guild cũng sẽ không nhận lại\n\n7. Sau khi đánh bại Thủ vệ ải cuối cùng - ải 150 sẽ tự động hồi sinh, Thủ Vệ này có thưởng sát thương mức cao"}
TAB_Describe[780] = {"1. Thành viên Guild mỗi ngày chỉ được xây dựng 1 lần (0h cài lại), chọn trong 3 loại xây dựng, xây dựng khác nhau đem lại lợi ích khác nhau\n\n2. Sau khi xây dựng được nhận EXP Guild và Cống Hiến Guild, xây dựng là cách quan trọng để tăng cấp Guild\n\n3. Sau khi xây dựng trong ngày nếu đổi Guild, không thể tiếp tục xây dựng"}
TAB_Describe[781] = {"1. Trưởng Guild có quyền hạn cao nhất trong Guild, như quyền sửa thông tin nội bộ Guild, quản lý thành viên, bổ nhiệm/bãi miễn Phó Guild\n2. Guild có thể gửi thông tin triệu hồi, sau khi gửi hiển thị ở kênh chat thế giới.\n3. Sau khi rời Guild, trong 12h không được gia nhập Guild khác.\n4. Xây dựng là con đường quan trọng nâng cao EXP Guild, nâng cao EXP Guild có thể tăng cấp Guild, sau khi Guild tăng cấp sẽ tăng thêm giới hạn tổng số người và giới hạn chức vị Phó Guild, còn được mở các lối chơi Guild.\n5. Trưởng Guild offline 3 ngày trở lên, mọi thành viên đều có thể tố cáo để thành Trưởng Guild mới.\n6. Mỗi loại Lì Xì Guild mỗi ngày chỉ được phát 10 lần, 00:00 mỗi ngày cài lại lượt."}
TAB_Describe[782] = {"1. Mỗi PB mỗi ngày có 2 lượt miễn phí khiêu chiến\n\n2. Tăng VIP có thể mua thêm lượt"}
TAB_Describe[783] = {"Mỗi Thần Khí đều có nhiệm vụ mở khóa riêng, hoàn thành nhiệm vụ chỉ định có thể mở khóa Thần Khí tương ứng, và mở nhiệm vụ riêng của Thần Khí"}
TAB_Describe[784] = {"1. Sau khi mang Thần Khí, thuộc tính Thần Khí này tăng thêm cho toàn đội Anh Hùng, hiệu quả tăng thêm chỉ sinh hiệu lực trong chiến đấu\n\n2. Có thể dùng mảnh Thần Khí tăng cấp Thần Khí, tăng buff thuộc tính Thần Khí \n\n3. Có thể dùng Nguồn Cội Thần Kỹ tăng cấp kỹ năng, tăng mạnh hiệu quả S.Thương kỹ năng\n\n4. Có thể dùng Đá Thần Luyện tăng cấp Tinh Luyện, tăng mạnh S.Thương kỹ năng của Thần Khí"}
TAB_Describe[785] = {"Mỗi Thần Khí kèm thêm 1 kỹ năng chủ động, lượt thứ 3 thi triển kỹ năng chủ động, mỗi 3 lượt thi triển 1 lần"}
TAB_Describe[786] = {"1. Thần Ấn có thể dùng Đá Thần Ấn tăng thuộc tính\n\n2. Số lượng Đá Thần Ấn có thể dùng do cấp Thần Khí quyết định"}
TAB_Describe[787] = {"1. Khi ghép chỉ có thể sử dụng Ấn Ký cùng loại, nếu không sẽ không thể ghép\n\n2. Ghép Ấn Ký bậc càng cao, cấp Học viên phải càng cao\n\n3. Mỗi lần ghép cần tối thiểu 2 Ấn Ký cùng loại\n\n4. Ghép Ấn Ký có tỷ lệ thất bại, sau khi thất bại Ấn Ký dùng để ghép sẽ được tách thành Tinh Hoa Ấn Ký\n\n5. Máy Tinh Hoa Ấn Ký có thể dùng để đúc lại Ấn Ký\n\n6. Mỗi lần ghép, số lượng Ấn Ký đặt vào càng nhiều thì tỷ lệ thành công càng cao\n\n7. Mỗi lần ghép thất bại cũng sẽ nhận điểm đúc, khi điểm đúc đạt 1000 có thể nhận 1 Ấn Ký Cam, đồng thời sẽ trừ đi điểm đúc tương ứng"}
TAB_Describe[788] = {"1. Sau khi đúc lại Ấn Ký, thuộc tính, kỹ năng và số lượng kỹ năng đều có cơ hội thay đổi\n\n2. Mỗi lần đúc lại đều sẽ tốn Tinh Hoa Ấn Ký và Vàng, phẩm Ấn Ký càng cao cần Tinh Hoa Ấn Ký và Vàng càng nhiều\n\n3. Khi đúc lại Ấn Ký IV và Ấn Ký VI, số lượt đúc lại Ấn Ký cùng loại đạt chỉ định, chắc chắn ra Kỹ năng III hiếm (Cực hiếm)\n\n4. Tách Ấn Ký có thể nhận Tinh Hoa Ấn Ký\n\n5. Hiệu quả kỹ năng cùng loại không thể cộng dồn, chỉ có hiệu lực ở cấp cao nhất"}
TAB_Describe[789] = {"Nhận"}
TAB_Describe[790] = {"1. Mỗi 1 lần Tầm Bảo sẽ nhận một loại Bảo Vật ngẫu nhiên\n\n2. 0h mỗi ngày sẽ cài lại thưởng Vòng Quay\n\n3. Mỗi lần Tầm Bảo đều có cơ hội nhận: Trang bị lớn mạnh, Anh Hùng lớn mạnh 5 sao, Anh Hùng 4 sao ngẫu nhiên... \n\n4. Mỗi lần Tầm Bảo đều nhận được 10 điểm May Mắn, đạt 1000 điểm May Mắn có thể nhận Quà May Mắn\n\n5. Mỗi lượt Tầm Bảo Thường đều sẽ nhận điểm Tầm Bảo, có thể dùng để đổi vật phẩm trong Cửa Hàng Tầm Bảo\n\n6. Cửa Hàng Tầm Bảo tự động làm mới vào 0h mỗi ngày"}
TAB_Describe[791] = {"Không có thưởng"}
