TAB_Describe[803] = {"Anh Hùng này đang làm nhiệm vụ"}
TAB_Describe[804] = {"Anh Hùng cần điều phái đã đầy"}
TAB_Describe[805] = {"1. Trong lối chơi này, người chơi phải tổ đội (tối đa 5 Anh Hùng) liên tục chiến đấu nhiều trận, ải sau sẽ khó hơn ải trước đó; Số lần vượt ải càng nhiều thưởng càng hậu hĩnh\n\n2. Không giới hạn số lượt khiêu chiến mỗi ngày, 00:00 mỗi ngày dựa vào lịch sử ghi chép cao nhất để làm mới số ải khởi điểm, lấy số ải đó cộng thêm 10 ải để làm số ải khởi điểm\n\n3. Trước khi khiêu chiến có thể chọn 1 anh hùng chi viện mà bạn bè của server này đã phái đi tham chiến, nhưng lực chiến của anh hùng đó không được vượt quá lực chiến của anh hùng viện trợ cao nhất *120% của bản thân\n\n4. Sau khi anh hùng chi việc được bạn bè trưng dụng, sẽ nhận được thưởng điểm tình bạn, thưởng sẽ được gửi qua thư.\n\n5. Trong quá trình chiến đấu không được đổi Anh Hùng và chiến thuật, trong chiến đấu, lượng HP của anh hùng đã mất, kỹ năng đã dùng và CD kỹ năng đều sẽ được kế thừa ở ải tiếp theo; Cho đến khi toàn bộ Anh Hùng tử vong, kết thúc khiêu chiến\n\n6. Người chơi có thể rời khiêu chiến giữa chừng, sau khi rời sẽ dựa vào thành tích vượt ải để tổng kết thưởng; Nếu người chơi dừng lại lâu ở giai đoạn chọn hiệu quả buff, hệ thống sẽ tự động giúp người chơi chọn ngẫu nhiên 1 buff, tiếp tục khiêu chiến\n\n7. Sau khi vào khiêu chiến, người chơi chọn 1 hiệu quả buff tăng cường lực chiến, sau đó cứ 5 ải sẽ được lựa chọn 1 lần."}
TAB_Describe[806] = {"1. Thưởng ngày: Trong khiêu chiến ngày, bắt đầu tính từ điểm khởi đầu, cứ vượt 1 ải sẽ tăng 1 lần khiêu chiến, mỗi ngày thưởng mỗi ải chỉ được tăng 1 lần, 00:00 mỗi ngày cài lại; Nội dung thưởng là Vàng, EXP Anh Hùng\n\n2. Thưởng vượt ải lần đầu: Cứ thắng 5 đợt quái được nhận một phần thưởng, nhận thủ công, thưởng này chỉ nhận 1 lần\n\n3. Thưởng BXH: 00:00 mỗi ngày, căn cứ theo xếp hạng trong BXH số ải khiêu chiến để tổng kết và phát thưởng, hãy cố gắng khiêu chiến thật nhiều ải nhé!"}
