TAB_Describe[810] = {"Rời chiến đấu"}
TAB_Describe[811] = {"1. Tốc chiến có thể trực tiếp nhận 120 phút lợi ích treo máy ải hiện tại\n\n2. Lần đầu tốc chiến mỗi ngày được miễn phí, 00:00 cài lại số lượt\n\n3. Sau khi kích hoạt đặc quyền tốc chiến, mỗi ngày được miễn phí tốc chiến 3 lần (1+2), và có thêm 8 (3+5) cơ hội mua thêm\n\n4. Ngoài ra cần chú ý: Khi mở SK 'Tác chiến nhanh', sẽ tăng thêm 4 cơ hội mua."}
