TAB_Describe[869] = {"1. Làm mới có thể xuất hiện Nhiệm vụ Lịch Luyện phẩm cao, phẩm nhiệm vụ càng cao thưởng càng nhiều\n\n2. Mỗi ngày có 2 lần làm mới miễn phí, cũng có thể dùng Vé Làm Mới hoặc Kim Cương để làm mới\n\n3. Trong giao diện điều phái, điều kiện hoàn thành biểu thị cấp sao anh hùng cần đáp ứng, còn lại là điều kiện đội hình mà anh hùng cần đáp ứng\n\n4. Khi anh hùng đủ điều kiện điều phái, có thể dùng điểm Lịch Luyện nhất định để nhận nhiệm vụ tương ứng\n\n5. Sau mỗi lần nhận nhiệm vụ cần tiến hành trong một thời gian, trong lúc đó anh hùng đã được điều phái không thể làm nhiệm vụ khác\n\n6. Khi {Điểm Lịch Luyện sở hữu} và {Điểm Lịch Luyện tích lũy nhận} đạt giới hạn, treo máy offline sẽ không thể nhận thêm điểm Lịch Luyện nữa."}
TAB_Describe[870] = {"1. 4 nghề Chiến Binh, Pháp Sư, Tank, Hỗ Trợ tương ứng với các kỹ năng của Guild, mỗi loại chỉ thêm lợi ích cho nghề tương ứng\n\n2. Người chơi kích hoạt các kỹ năng của mỗi vòng trong nghề để bắt đầu giai đoạn tiếp theo của vòng kỹ năng\n\n3. Sau khi người chơi thoát hoặc bị loại khỏi Guild, các kỹ năng của Guild sẽ mất hiệu quả; lần sau khi tham gia Guild khác, kỹ năng sẽ tiếp tục có hiệu quả và kỹ năng đã nâng cấp sẽ được giữ lại\n\n4. Sau khi các kỹ năng thường được cài lại, cấp của những kỹ năng thường này sẽ bị xóa, đồng thời hoàn trả tất cả 50% Vàng và 100% Cống Hiến Guild đã tốn. Tổng cấp độ của các kỹ năng thường càng cao, cài lại càng tốn nhiều Kim Cương. Lần cài lại đầu tiên của kỹ năng thường chỉ tốn 300 Kim Cương\n\n5. Sau khi cài lại kỹ năng PVP, các thuộc tính PVP và cấp kỹ năng của hệ thống sẽ bị xóa, đồng thời hoàn trả tất cả 100% Vật Liệu Dưỡng đã tốn, tổng cấp thuộc tính PVP càng cao, Kim Cương tốn để cài lại càng cao. Lần cài lại kỹ năng PVP đầu tiên chỉ tốn 30 Kim Cương \n\n6. Nâng cấp thuộc tính PVP trong giai đoạn đầu bị hạn chế bởi tất cả các cấp thuộc tính của nghề này, giai đoạn sau bị hạn chế của tất cả các cấp thuộc tính của 3 nghề (bao gồm cả nghề này)"}
