TAB_Describe[1125] = {"Trở về tìm kiếm"}
TAB_Describe[1126] = {"%s đạt %s sao mở khóa"}
TAB_Describe[1127] = {"1. Trong Đấu Trường, những người chơi khác có thể khiêu chiến SV này, có thể tăng điểm Chiến Đấu\n\n2. Mỗi ngày có 3 cơ hội khiêu chiến miễn phí và có thể tốn Kim Cương mua thêm lượt\n\n3. 7 ngày là 1 mùa giải, thưởng xếp hạng được tính vào 21:00 ngày thứ 7 của mỗi mùa giải, điểm Chiến Đấu sau khi tổng kết lúc 23:59 là 70% hiện tại, tối thiểu là 1000\n\n4. Sau khi mùa giải đủ 10 trận, sẽ mở tính năng bỏ qua"}
TAB_Describe[1128] = {"1. Giải Vô Địch Chiến Đấu bao gồm Vòng Loại và Top 32 tạo thành\n\n2. Vào ngày thứ 3 và thứ 6 của mỗi mùa giải Chiến Đấu, chọn ra Top 128 người chơi trên BXH giải chiến đấu tự động tham đấu\n\n3. Hình thức thi đấu là kiểu đối kháng 1V1\n\n4. Nếu trận đấu quá thời gian, phe có tổng sát thương cao hơn sẽ thắng\n\n5. Nếu không đủ 4 người chơi đáp ứng điều kiện tham gia thì giải vô địch sẽ không được mở."}
TAB_Describe[1129] = {"1. Vòng Loại sẽ mở lúc 21:05, với tổng cộng 6 vòng. Mỗi vòng thi được chia thành giai đoạn chuẩn bị (để thay đổi đội hình), giai đoạn dự đoán (để tham dự đoán) và giai đoạn chiến đấu\n\n2. Thắng mỗi vòng thi đấu nhận được điểm Vòng Loại, thất bại không nhận điểm\n\n3. Tổng điểm cuối cùng bằng điểm Vòng Loại thêm tỷ lệ nhất định của điểm Chiến Đấu. Top 32 người chơi có tổng điểm cao nhất sẽ tham gia vào trận đấu Top 32"}
TAB_Describe[1130] = {"1. Thi đấu Top 32 bắt đầu sau khi Vòng Loại kết thúc, chia 4 nhóm tiến hành. Hình thức đấu loại trực tiếp, cuối cùng xác định Top 1, Top 2, Top 3\n\n2. Top 3 được xác định bằng tổng điểm cao nhất trong Top 4."}
TAB_Describe[1131] = {"1. Mỗi vòng đấu mở dự đoán một trận đấu chỉ định, có thể đặt cược trong giai đoạn dự đoán. Mỗi vòng chỉ đặt cược 1 lần, không thể thay đổi\n\n2. Bắt đầu mỗi vòng, sẽ phát Chip Đặt Cược dùng để dự đoán\n\n3. Dự đoán đúng nhận được Chip Đặt Cược theo tỉ lệ cược tương ứng, nếu sai sẽ trừ số Chip Đặt Cược đã cược.\n\n4. Sau khi giải vô địch chiến đấu kết thúc, Chip Đặt Cược sẽ tự đổi thành Danh Vọng Chiến Đấu dùng để đổi trong Cửa Hàng Điểm"}
TAB_Describe[1132] = {"1. Sau khi Giải Vô Địch Chiến Đấu kết thúc dựa vào xếp hạng cuối cùng để gửi thưởng qua thư"}
TAB_Describe[1133] = {"Quy tắc cơ bản"}
TAB_Describe[1134] = {"Quy tắc Vòng Loại"}
TAB_Describe[1135] = {"Quy tắc Top 32"}
TAB_Describe[1136] = {"Quy tắc dự đoán"}
TAB_Describe[1137] = {"Phát thưởng"}
TAB_Describe[1138] = {"1. XH Đấu Trường khi đạt danh hiệu chỉ định có thể khiêu chiến, điều kiện xếp hạng để khiêu chiến 3 BOSS Thần Vị là Top 10, Top 20, Top 30\n\n2. Sau khi khiêu chiến BOSS Thần Vị thành công, người chơi sẽ nhận được Quyền Quán Quân Thần Vị này, nhận được tôn hiệu Dũng Sĩ tương ứng, gắn tôn hiệu có thể nhận thuộc tính Buff mạnh mẽ, đồng thời năng lực của BOSS Thần Vị này sẽ mạnh thêm\n\n3. Nếu người chơi đang ở BOSS Thần Vị bị người khác khiêu chiến thành công, thì Thần Vị này sẽ trao cho người đó, đồng thời người chơi trước sẽ mất đi tôn hiệu Dũng Sĩ.\n\n4. Mỗi người chỉ được chiếm 1 vị trí, trong thời gian tại vị nếu khiêu chiến thành công các BOSS Thần Vị khác, sẽ mất vị trí ban đầu\n\n5. Khiêu chiến thất bại có 20 phút thời gian CD, thời gian này không thể khiêu chiến bất kỳ BOSS Thần Vị nào"}
