TAB_Describe[1492] = {"Xuyên Không"}
TAB_Describe[1493] = {"Like đã đạt giới hạn"}
TAB_Describe[1494] = {"Thu thập đã đạt giới hạn"}
TAB_Describe[1495] = {"1. Thời gian mở Xâm Lược Xeno: 00:00, cứ 48h cài lại 1 lần, 10p trước khi cài lại người chơi không thể phát động sự kiện\n\n2. Sau khi cài lại tất cả sự kiện sẽ tạo lại, Chip tích lũy nhận được vòng này sẽ biến mất\n\n3. Người chơi đến ô bên cạnh để khám phá \n\n4. Người chơi cứ đạt 1 ô, ô khác cùng hàng sẽ bị hủy, hãy chọn đường cẩn thận\n\n5. Huy Chương Xeno nhận được khi đánh bại Thủ Vệ có thể đổi vật phẩm tương ứng ở Tiệm Xeno\n\n6. Chip là một vật phẩm đặc biệt, chỉ hiệu lực và xem được trong không gian Xeno, không có hiệu quả với chiến đấu Ngoại Giới\n\n7. Thưởng càng hấp dẫn thì rủi ro càng cao, có thể thuê anh hùng, giúp khiêu chiến sẽ thuận lợi hơn"}
TAB_Describe[1496] = {"Mê Cung Ảo Cảnh cứ 2 ngày mở 1 vòng, chọn 5 anh hùng tiến hành Khám Phá, giữa đường không thể đổi anh hùng\n\nMỗi lần Mê Cung Ảo Cảnh mở, quay lại 5 tầng theo tầng cao nhất lịch sử"}
TAB_Describe[1497] = {"Tầng Thường"}
TAB_Describe[1498] = {"Mỗi Thủ Vệ bảo vệ một số khu vực, đánh bại Thủ Vệ xong ô gần bên tự động mở khóa\n\nTiêu diệt tất cả Thủ Vệ xong, boss xuất hiện, đánh bại boss vào tầng tiếp theo thông qua cổng dịch chuyển\n\nSau khi vào tầng sau, không thể trở về tầng trước"}
TAB_Describe[1499] = {"Chiến đấu Tầng Thường"}
TAB_Describe[1500] = {"Tất cả chiến đấu đều là khiêu chiến đơn 1v1, khi HP một phe là 0 hoặc lượt đạt tối đa chiến đấu kết thúc, sau khi chiến đấu kết thúc 2 bên duy trì điểm HP, sau khi điểm HP về 0 không thể tiếp tục chiến đấu"}
TAB_Describe[1501] = {"Sự kiện Tầng Thường"}
TAB_Describe[1502] = {"Mê Cung Ảo Cảnh có nhiều sự kiện, hoàn thành sự kiện khác nhau nhận thưởng khác nhau: \n\nThủ Vệ: đánh bại Thủ Vệ mạnh trong Ảo Cảnh có thể khám phá khu vực xung quanh\n\nThưởng: khám phá xong tự động thu thập và nhận thưởng\n\nĐố Vui: trả lời đúng có thưởng, trả lời sai không bị phạt\n\nKhám phá buff: nhận được buff, vòng này có hiệu quả với tất cả anh hùng\n\nChúc phúc: nhận được Thuốc HP và Thuốc Thanh Tẩy\n\nPoker: đoán trúng tỉ lệ nhân khác nhau nhận được thưởng càng cao"}
TAB_Describe[1503] = {"Quy tắc càn quét"}
TAB_Describe[1504] = {"1. Sau khi lực chiến người chơi vượt quá 200w mở tự động trả lời, vượt quá 400w mở càn quét\n\n2. Mỗi lần càn quét tốn 1 lượt càn, sẽ tiêu diệt tất cả quái của tầng này. Mỗi vòng Mê Cung Ảo Cảnh chỉ được càn quét 6 lần"}
TAB_Describe[1505] = {"Tiệm Mê Cung"}
TAB_Describe[1506] = {"1 .Khám Phá gặp Tiệm Thần Bí, tương tác Tiệm xong, vật phẩm sẽ xuất hiện ở Tiệm Ảo Cảnh\n\n2. Sau khi dùng Tiệm Xuyên Không, vật phẩm xuất hiện ở Tiệm Ảo Cảnh\n\n3. Vật phẩm trong Tiệm Ảo Cảnh sẽ biến mất sau khi Khám Phá lần này cài lại"}
TAB_Describe[1507] = {"1. 6 anh hùng cấp cao nhất tự động trở thành anh hùng dịch chuyển năng nguyên, khi cấp bằng nhau sẽ ưu tiên đặt vào anh hùng có lực chiến cao nhất\n\n2. Anh hùng đặt vào ô sẽ tăng cấp Tháp Cộng Hưởng, cấp sao anh hùng không đổi, cấp sau khi tăng vẫn chịu giới hạn của cấp phẩm chất anh hùng\n\n3. Anh hùng đặt vào ô thức tỉnh bình thường, có thể dùng trong các lối chơi, nhưng không thể tiến hành tăng cấp, điều trả, quay lại...\n\n4. Khi anh hùng rời khỏi ô, ô bắt đầu 24h thời gian CD, hết thời gian CD có thể đặt anh hùng lại, tốn Kim Cương làm mới ngay thời gian CD \n\n5. Khi anh hùng bị động rời khỏi ô, ô không vào thời gian CD\n\n6. Ô Tháp Cộng Hưởng tốn Đá Cộng Hưởng để mở, Đá Cộng Hưởng nhận được khi treo máy ở PB Cốt Truyện."}
