TAB_Describe[1523] = {"Giải Vô Địch Võ Đạo-Thủ"}
TAB_Describe[1524] = {"Độ Thân Thuộc"}
TAB_Describe[1525] = {"Hãy mở khóa Thần Khí hiện tại trước"}
TAB_Describe[1526] = {"Thiếu nữ Tinh Linh tóc dài màu bạc và đôi mắt màu đỏ tím, người ứng cử vương vị đời thứ 42 của vương quốc. Do huyết thống lai Tinh Linh tóc bạc, nên bị mọi người ghét. Nhưng tính cách thiện lương ôn nhu, còn có khả năng thi pháp xuất sắc."}
TAB_Describe[1527] = {"Cấp Tháp Cộng Hưởng quyết định cấp anh hùng trong ô"}
TAB_Describe[1528] = {"Hôm nay đã nhận quà, ngày mai lại đến nhé"}
TAB_Describe[1529] = {"1. Điều trả anh hùng nhận được Đá Tiến Bậc nhất định và vật liệu dưỡng anh hùng khác\n\n2. Điều trả anh hùng xong, hoàn trả toàn bộ vật liệu dưỡng tiêu hao (Bao gồm vật liệu tăng cấp, vật liệu tiến bậc), và tự động tháo gỡ trang bị và Chip, kỹ năng Thiên Phú đã học hoàn trả thành linh kiện Chip số lượng nhất định\n\n3. Mảnh Anh Hùng có thể phân tách ở Túi, đổi lượng ít tài nguyên\n\n4. Anh hùng 4 sao trở lên không thể đặt vào nhanh, cần nhấp đặt vào từng cái\n\n5. Anh hùng 7 sao trở lên không thể điều trả. Nếu cần, vui lòng đến tính năng chuyển đổi Xuyên Không để quay lại"}
TAB_Describe[1530] = {"1. Phòng Nghiên Cứu có thể ghép anh hùng sao thấp thành anh hùng sao cao cùng tên, anh hùng 4 sao ghép thành 5 sao, anh hùng 5 sao có thể ghép thành 6 sao\n\n2. Anh hùng ghép thành công xong sẽ kế thừa cấp anh hùng chính và cấp tiến bậc\n\n3. Ghép thành công xong, anh hùng làm vật liệu sẽ hoàn trả tất cả vật liệu dưỡng tốn (Bao gồm vật liệu tăng cấp, vật liệu tiến bậc), và tự động tháo gỡ trang bị và Chip"}
TAB_Describe[1531] = {"Không có anh hùng có thể chuyển đổi"}
TAB_Describe[1532] = {"1. Sau khi tổng kết lúc 20:00 trong ngày Guild Chiến, Guild thắng có thể tăng EXP Tiệm\n\n2. Thành viên tham chiến càng nhiều, EXP Tiệm có thể tăng càng nhiều\n\n3. EXP Tiệm tăng đến điều kiện nhất định xong, Tiệm tự động tăng cấp\n\n4. Khi Tiệm đạt cấp khác nhau, mở khóa một số vật phẩm, tốn Kim Cương để mua\n\n5. Vật phẩm trong Tiệm thuộc cá nhân, từng người mua không ảnh hưởng nhau\n\n6. Sau khi rời Guild, bảo lưu trạng thái mua trong Tiệm, sau khi vào lại Guild không cài lại"}
TAB_Describe[1533] = {"1. Sau khi tổng kết lúc 20:00 trong ngày Guild Chiến, thành viên tham chiến của Guild thắng tích lũy tiến độ nhiệm vụ 1 lần\n\n2. Sau khi rời Guild, bảo lưu tiến độ nhiệm vụ, sau khi vào Guild lại, hồi phục tiến độ nhiệm vụ"}
TAB_Describe[1534] = {"1. Guild Chiến mỗi tuần tổ chức 3 trận, thời gian bắt đầu lần lượt là 12:00 thứ 2,4,6\n\n2. Guild cấp 3 trở lên và số người sôi nổi trên 8 mới được tham chiến\n\n3. Guild Chiến là xếp cặp liên server, xếp cặp từng cặp Guild thực lực gần nhau thành đối thủ tương tác\n\n4. Nếu khi xếp cặp xuất hiện trống lượt (không xếp cặp được với đối thủ), không thể tham gia Guild Chiến lần này"}
TAB_Describe[1535] = {"1. Rương sinh ra sau khi Guild Chiến kết thúc, chỉ có Guild tham gia Guild Chiến mới nhận được\n\n2. Rương có 2 loại: Rương Cao Cấp phe thắng, Rương Thường phe thua\n\n3. Số lượng Rương sản sinh dựa theo số người sôi nổi Guild (1vs1), chỉ có thành viên Sôi Nổi mới có thể mở rương, mỗi người chỉ mở 1 lần\n\n4. Người chơi mở rương nhận được Cống Hiến Guild nhất định, có xác suất được lượng lớn Cống Hiến Guild"}
TAB_Describe[1536] = {"1. Luyện Kim mỗi ngày sẽ làm mới 3 lần, mỗi lần làm mới đều cài lại số lần còn Luyện Kim\n\n2. Thời gian Luyện Kim làm mới mỗi ngày: 0: 00, 9: 00, 19: 00\n\n3. Tăng cấp VIP có thể tăng số lượng Vàng nhận"}
TAB_Describe[1537] = {"1. Có thể hủy hẹn anh hùng 7, 8 sao và 9 sao, hủy hẹn xong được nhận Búp Bê Anh Hùng hệ này và Thẻ Bản Thể số lượng nhất định\n\n2. Hủy hẹn hoàn trả tất cả vật phẩm dưỡng anh hùng tốn"}
TAB_Describe[1538] = {"1. Có thể chuyển đổi anh hùng 10-13 sao trở lên thành anh hùng khác, chuyển đổi cần bản thể và mấy anh hùng khác tương đồng (10 sao cần 5, 11 sao cần 7, 12 sao cần 9, 13 sao cần 11...), mấy anh hùng đã chọn tương đồng khác được gọi là anh hùng sẽ chuyển đổi ra\n\n2. Giữa chiến đấu Ma Pháp - Khoa Học có thể chuyển đổi qua lại, giữa Thần Minh và Ác Ma có thể chuyển đổi qua lại\n\n3. Anh hùng phe Hỗn Loạn không thể tiến hành chuyển đổi\n\n4. Mọi dưỡng liên quan hoàn thiện sau khi chuyển đổi sẽ hoàn trả toàn bộ\n\n5. Cần đặc biệt chú ý: Sau khi chuyển đổi thành công, Thẻ Bản Thể của anh hùng trước chuyển đổi sẽ không hoàn trả"}
TAB_Describe[1539] = {"1. Anh Hùng bất kỳ 10-13 sao trở lên có thể hủy hẹn, sau khi hủy hẹn anh hùng giảm xuống 9 sao\n\n2. Anh hùng hủy hẹn sẽ tốn Thư Giải Ước cấp cao, cấp sao anh hùng hủy hẹn khác nhau, số lượng vật phẩm tốn khác nhau\n\n3. Sau khi anh hùng hủy hẹn, trang bị anh hùng, chuyên thuộc, Chip kế thừa không đổi; trả về vật liệu thức tỉnh bằng hình thức Búp Bê; Thiên Phú 11, 13 sao trả về Chip Thiên Phú của nó, và 100% trả về Vàng dưỡng tốn, EXP, Đá Tiến Bậc, vật liệu hoàn thiện...\n\n4. Khi hủy hẹn, anh hùng vượt giới hạn cấp sẽ giảm xuống cấp 205"}
TAB_Describe[1540] = {"#C(#FFFFFF)Lượt mua còn: #C(#00E400)%s"}
TAB_Describe[1541] = {"Thế Giới Hỗn Loạn"}
TAB_Describe[1542] = {"1. Tổng cộng có 5 phụ bản lớn gồm Khoa Học, Ma Pháp, Chiến Đấu, Thần Minh, Ác Ma, lần lượt mở từ thứ 2 đến thứ 6, cuối tuần mọi phụ bản đều mở\n\n2. Mỗi phụ bản có 12 tầng, sau khi vượt mỗi tầng có thể mở càn quét tương ứng\n\n3. Khi phụ bản mở cuối tuần thì tiếp tục tiến độ các phụ bản từ thứ 2 đến thứ 6\n\n4. 0h thứ 2 cài lại phụ bản, tiến độ mọi phụ bản sẽ được xóa\n\n5. Vật liệu nhận trong phụ bản có thể dùng tăng cấp và tiến bậc trong Thánh Văn các phe"}
TAB_Describe[1543] = {"Lượt khiêu chiến"}
TAB_Describe[1544] = {"1. Lượt khiêu chiến dùng chung cho mọi phụ bản\n\n2. Khiêu chiến thất bại không tốn lượt\n\n3. Lượt khiêu chiến cập nhật 0 giờ mỗi ngày\n\n4. Mỗi ngày có thể dùng thêm Kim Cương mua 2 lần lượt khiêu chiến"}
TAB_Describe[1545] = {"1. Mỗi tuần ghi chép tổng lượt vượt ải phụ bản của người chơi, càn quét không tính\n\n2. 0h thứ 2 dựa vào xếp hạng phát thưởng tương ứng, đồng thời cài lại số lần vượt ải"}
TAB_Describe[1546] = {"1. Từ ngày 7 mở server, người chơi cấp 60 trở lên có thể tham gia thí luyện Tấn Công Thứ Nguyên\n\n2. Sau khi làm mới BOSS, mỗi người mỗi ngày được miễn phí khiêu chiến 2 lần Tấn Công Thứ Nguyên\n\n3. Tổng sát thương tạo thành với BOSS trong ngày sự kiện sẽ tính gộp ở BXH, 22h phát thưởng theo xếp hạng tổng sát thương tạo cho BOSS\n\n4. 22h trong ngày làm mới Boss, đóng Tấn Công Thứ Nguyên\n\n5. Điểm thưởng nhận được có thể đổi các vật phẩm ở Tiệm Tấn Công Thứ Nguyên\n\n6. Dựa vào điểm tích lũy sát thương toàn SV, phát thưởng toàn SV trong mốc này, hệ thống sẽ ngẫu nhiên phát một phần thưởng may mắn cho người chơi tham gia."}
TAB_Describe[1547] = {"1. Sau khi mở khóa tiếp ứng, có thể hẹn, tặng quà, tăng cấp kỹ năng, du lịch, có thể thêm thuộc tính cho toàn anh hùng\n\n2. Thuộc tính thêm cho toàn anh hùng tiếp ứng đều cộng dồn\n\n3. Có thể hẹn ngẫu nhiên, mỗi lần tốn 1 điểm tâm trạng, giới hạn tâm trạng liên quan với cấp VIP, cấp càng cao, giới hạn càng cao\n\n4. Tâm trạng có thể tự động phục hồi qua thời gian, cứ 3 tiếng tự động phục hồi 1 điểm tâm trạng, khi tâm trạng đạt giới hạn, không tự phục hồi nữa\n\n5. Tiếp ứng có thể xuất chiến, trong chiến đấu được thi triển kỹ năng tiếp ứng, sau 1 lượt kỹ năng tiếp ứng trong chiến đấu, thi triển bằng tay, cứ 4 lượt thi triển 1 lần\n\n6. Linh thú có thể tăng buff thuộc tính tiếp ứng và kích hoạt linh sủng tiếp ứng, sau khi linh thú kích hoạt hoặc tăng bậc có thể sinh hiệu lực.\n\n7. Linh thú ra trận theo tiếp ứng, tăng cấp linh thú kích hoạt Duyên phận có thể tăng cấp kỹ năng linh sủng. "}
TAB_Describe[1548] = {"Điều trả nhanh"}
TAB_Describe[1549] = {"Tính năng điều trả nhanh dùng để điều trả Anh Hùng 1, 2, 3 sao, nhưng Anh Hùng 3 sao mỗi phe sẽ tự lưu lại 20 (Phe có Anh Hùng 3 sao ít hơn 20 sẽ lưu lại toàn bộ, không bị điều trả)"}
TAB_Describe[1550] = {"Thánh Văn hiện tại đã là cấp 0, không thể cài lại"}
TAB_Describe[1551] = {"Ghép vật phẩm"}
TAB_Describe[1552] = {"Ghép tốn"}
TAB_Describe[1553] = {"Tạm không ghi chép"}
TAB_Describe[1554] = {"1. Thánh Văn cơ bản tổng có 5 hệ, có thể dùng anh hùng 5 sao cùng hệ mở khóa. Sau khi mở khóa dựa vào thuộc tính Thánh Văn để tăng mọi thuộc tính của anh hùng cùng hệ\n\n2. Mở khóa Thánh Văn xong có thể dùng Vàng và Đá Thánh Văn tương ứng tăng thuộc tính và cấp Thánh Văn\n\n3. Thánh Văn cứ 10 cấp có thể tăng 1 bậc, sau khi tiến bậc tăng thêm tỉ lệ tốc độ và thuộc tính của tất cả anh hùng phe mình\n\n4. Búp Bê Anh Hùng không thể làm vật liệu mở khóa Thánh Văn\n\n5. Thánh Văn Hỗn Loạn không thể thao tác bằng tay"}
