TAB_Describe[1570] = {"#C(#FFFFFF)Tặng bạn %s thành công, nhận #I(T0)res/icon/ItemSmall/itemsmall_%s.png#C(#17FF63)%s"}
TAB_Describe[1571] = {"#C(#FFFFFF)Tốn #I(T0)res/icon/ItemSmall/itemsmall_%s.png#C(#17FF63)%s#C(#FFFFFF), nhận #C(#%s)%s"}
TAB_Describe[1572] = {"1. Phụ linh trang bị có thể tăng cấp kỹ năng tương ứng của Anh Hùng\n\n2. Vũ khí tương ứng kỹ năng 1, mũ tương ứng kỹ năng 2, trang phục tương ứng kỹ năng 3, giày tương ứng kỹ năng 4\n\n3. Cấp phụ linh bị hạn chế bởi cấp sao và phẩm trang bị, chỉ có trang bị Đỏ mới được Phụ Linh, cấp Phụ Linh không được vượt quá cấp sao trang bị. tối đa 5 cấp\n\n4. Gỡ trang bị sẽ mất buff cấp kỹ năng đã có"}
TAB_Describe[1573] = {"Trùng phụ"}
TAB_Describe[1574] = {"#C(#FFFFFF)Triệu hồi ngẫu nhiên #C(#FFDD33)1#C(#FFFFFF) hoặc #C(#FFDD33)10#C(#FFFFFF) #C(#FFDD33)1~5#C(#FFFFFF) sao"}
TAB_Describe[1575] = {"#C(#FFFFFF)Triệu hồi ngẫu nhiên #C(#FFDD33)1#C(#FFFFFF) hoặc #C(#FFDD33)10#C(#FFFFFF) #C(#FFDD33)2~5#C(#FFFFFF) sao"}
