TAB_Describe[1578] = {"00M"}
TAB_Describe[1579] = {"Chip Thường"}
TAB_Describe[1580] = {"Chip Cao Cấp"}
TAB_Describe[1581] = {"Xâm Lược Xeno tầng %s"}
TAB_Describe[1582] = {"1. Giải Vô Địch Võ Đạo tạo thành bởi Vòng loại và giải Top 64\n\n2. 12-13h mỗi chủ nhật, hệ thống sẽ chọn ra Top 256 người chơi Vòng loại Võ Đạo tự động dự giải\n\n3. Số người có tư cách tham dự cần đủ 64, nếu không giải đấu không thể mở\n\n4. Hình thức thi đấu là đối kháng đội hình đơn 1V1\n\n5. Khi chiến đấu quá giờ, tổng sát thương bên cao hơn sẽ thắng"}
TAB_Describe[1583] = {"1. Vòng loại mở vào 12:00 chủ nhật, tổng có 6 vòng đấu. Mỗi vòng phân thành giai đoạn chuẩn bị (dùng để đổi đội hình), giai đoạn dự đoán (dùng để tham gia lối chơi dự đoán) và giai đoạn chiến đấu\n\n2. Mỗi vòng thắng nhận điểm Vòng loại, thất bại không được điểm\n\n3. Tổng điểm cuối cùng bằng điểm tuyển chọn cộng điểm xếp hạng Vòng loại Võ Đạo, xếp hạng càng cao, điểm ban đầu càng cao. Người chơi Top 64 sẽ tham gia thi đấu Top 64"}
TAB_Describe[1584] = {"Quy tắc giải Top 64"}
TAB_Describe[1585] = {"1. Giải Top 64 mở sau khi Vòng loại kết thúc, phân thành 8 nhóm tiến hành. Cơ chế là đấu loại, cuối cùng chọn ra top 1, top 2, top 3\n\n2. Top 3 quyết định bởi tổng điểm cao thấp trong Vòng loại từ Top 4"}
TAB_Describe[1586] = {"1. Mỗi vòng đấu sẽ phát dự đoán đối với một trận chỉ định, có thể cược trong giai đoạn dự đoán. Mỗi vòng chỉ cược 1 lần, không thể thay đổi\n\n2. Khi bắt đầu mỗi vòng sẽ phát Xu Dự Đoán Cao Cấp dùng để dự đoán\n\n3. Dự đoán chính xác nhận được Xu Dự Đoán Cao Cấp tương ứng, sai bị trừ Xu Dự Đoán Cao Cấp đặt cược\n\n4. Sau khi giải Vô Địch Võ Đạo kết thúc, Xu Dự Đoán Cao Cấp tự động tính toán thành Xu Quán Quân đổi vật phẩm ở Tiệm Quán Quân"}
TAB_Describe[1587] = {"1. Sau khi giải Vô Địch Võ Đạo kết thúc, phát thưởng qua thư theo xếp hạng cuối cùng"}
