TAB_Describe[1628] = {"1. Mỗi Bảo Thạch Ma Lực có thể triệu hồi 1 lần Anh Hùng trong thẻ thuộc tính tương ứng\n\n2. Triệu hồi có xác suất nhận Mảnh và Anh Hùng phẩm Cam hoặc Tím\n\n3. Mỗi lần triệu hồi sẽ nhận 1 Thẻ Anh Hùng, Thẻ Anh Hùng có thể đổi Anh Hùng 5 sao chỉ định trong đổi Anh Hùng\n\n4. Mỗi lần Triệu Hồi Hệ sẽ nhận 30 Lệnh Xuyên Không, tốn số lượng Lệnh Xuyên Không nhất định có thể đổi vật phẩm trong Tiệm Triệu Hồi"}
TAB_Describe[1629] = {"1. Tốn Lệnh Xuyên Không, có thể tiến hành chuyển đổi Anh Hùng 4, 5 sao ngoại trừ phe Thần Minh và Ác Ma\n\n2. Mỗi lần chỉ có thể chuyển hóa Anh Hùng thành Anh Hùng khác\n\n3. Anh Hùng mới sẽ kế thừa tất cả thuộc tính của Anh Hùng trước"}
