TAB_Describe[1675] = {"1. Mỗi ô Thiên Phú có thể dùng Chip Kỹ Năng tương ứng để anh hùng lĩnh hội được kỹ năng tương ứng, có thể dùng Tinh Hoa Phù Văn để mua Chip Kỹ Năng trong {Tiệm Kỹ Năng}\n\n2. Có thể dùng Chip Kỹ Năng tương ứng để tăng cấp kỹ năng đã lĩnh hội\n\n3. Có thể dùng kỹ năng {Quên} để lĩnh hội lại kỹ năng\n\n4. Sau khi dùng kỹ năng {Quên} sẽ trả lại toàn bộ vật liệu dưỡng\n\n5. Nếu kỹ năng lĩnh hội và kỹ năng Ấn Ký đều cùng loại thì chỉ có hiệu lực với kỹ năng cao cấp\n\n6. Anh hùng 13 sao sẽ mở kế hoạch hoàn thiện nhân loại, nhận được thuộc tính và kỹ năng mới."}
TAB_Describe[1676] = {"Lv%s/bậc %s"}
TAB_Describe[1677] = {"Vui lòng đợi"}
TAB_Describe[1678] = {"1. Trưởng Guild có quyền hạn cao nhất trong Guild, như quyền sửa thông tin nội bộ Guild, quản lý thành viên, bổ nhiệm/bãi miễn Phó Guild...\n\n2 Guild có thể gửi thông tin chiêu mộ, sau khi gửi hiển thị ở kênh chat thế giới\n\n3. Sau khi rời Guild, trong 12h không được gia nhập Guild khác\n\n4. Xây dựng là con đường quan trọng nâng cao EXP Guild, nâng cao EXP Guild có thể tăng cấp Guild, sau khi Guild tăng cấp sẽ tăng thêm giới hạn thành viên và giới hạn chức vị Phó Guild, còn được mở các lối chơi Guild\n\n5. Khi Trưởng Guild offline 3 ngày, mọi thành viên đều có thể tố cáo để thành Trưởng Guild mới\n\n6. Mỗi loại Lì Xì Guild mỗi ngày chỉ được phát 10 lần, 00:00 mỗi ngày cài lại lượt."}
