TAB_Describe[1686] = {"1. Ngày 1 hàng tháng cài lại toàn bộ thưởng\n\n2. Dựa vào lượt ký tên tích lũy phát thưởng\n\n3. Trong ngày nạp số tiền bất kỳ được nhận thêm 1 lần thưởng"}
TAB_Describe[1687] = {"1. Thời gian sự kiện, nhận được số lượng Anh Hùng 5 sao chỉ định có thể nhận thưởng mốc\n\n2. Sự kiện chỉ tính trạng thái ban đầu là Anh Hùng 5 sao, gồm: Triệu hồi, ghép mảnh, mở quà, nhận thưởng trực tiếp nhận\n\n3. Không tính: Anh Hùng từ 4 sao tăng lên 5 sao, thay đổi, điều trả lại\n\n4. Nếu sự kiện quy định vị trí triệu hồi, thì chỉ thống kê hành vi của vị trí chỉ định (Ví dụ: Triệu Hồi Cao Cấp, thì chỉ thống kê số lượng Triệu Hồi Cao Cấp)"}
