TAB_Describe[1807] = {"1. Dưới đây đã liệt kê mọi loại kỹ năng Thiên Phú, có thể nhận thông qua lĩnh hội Thiên Phú và mang Ấn Ký\n2. Hiệu quả kỹ năng cùng loại, bất kể trong Ấn Ký hay Thiên Phú, đều không thể cộng dồn, chỉ sinh hiệu lực theo cấp cao nhất\n3. Kỹ năng chuyên thuộc Thiên Phú chỉ nhận được thông qua lĩnh hội Thiên Phú, không thể nhận qua Ấn Ký\n4. Kỹ năng hiếm, đúc lại Ấn Ký đạt số lượng nhất định chắc chắn xuất hiện\n5. Liên kích, truy kích, bạo kích, trong một lượt chỉ kích hoạt 2 trong số đó (hơn nữa kích hoạt 1 lần), điều kiện giống nhau ưu tiên kích hoạt liên kích"}
