TAB_Describe[1871] = {"1. Phẩm:\n\n1. Phẩm Anh Hùng phân thành từ cao đến thấp:\nĐỏ (6 sao trở lên), Cam (5 sao), Tím (4 sao), \nLam(3 sao), Lục(2 sao), Trắng (1 sao).\n\n2. Phe: \n\n1. Tổng 5 phe: Khoa Học, Ma Pháp, Chiến Đấu, Thần, Ma.\n\n2. Quan hệ khắc chế giữa các phe: Khoa Học khắc\n chế Ma Pháp, Ma Pháp khắc chế Chiến Đấu, Chiến \nĐấu khắc chế Khoa Học, giữa Thần Ma khắc chế lẫn\n nhau.\n\n3. Bày trận:\n\n1. Được cùng lúc ra trận 5 Anh Hùng, thêm 1 Anh\n Hùng Viện Quân (Người chơi đạt Lv90 mở Viện\n Quân)\n\n2. Còn được ra trận Thần Khí (Người chơi Lv4 mở\n Thần Khí).\n\n3. Anh Hùng ra trận đạt điều kiện Phe nhất định,\nđược nhận buff thuộc tính loại bày trận.\n\n4. Bày trận có nhiều chiến thuật để chọn, chia ra:\n Nhẫn Phong, Linh Du, Lưu Tinh, Gai,Thần Đạo,\nThiên Khải."}
