TAB_Describe[1888] = {"1. 30 phút trước khi mở mỗi kỳ, 20 phút trước khi hết mỗi kỳ, đều là thời gian ngừng chiến, không thể vào khiêu chiến\n\n2. Khi mở sự kiện, dựa theo tình hình cụ thể của mỗi SV chia ra một số cụm Liên SV, quái và thuộc tính của tất cả người chơi trong mỗi cụm Liên SV đều như nhau\n\n3. Mỗi kỳ cùng lúc mở 3 boss, người chơi được đồng thời khiêu chiến 3 boss, mỗi boss có 5 độ khó: {Dễ}, {Thường}, {Khó} {Địa Ngục}, {Vô Tận} sau khi vượt độ khó trước sẽ mở độ khó sau\n\n4. Khiêu chiến Boss có thể nhận vật phẩm đổi thưởng SK ở Shop\n\n5. Khiêu chiến Boss được điểm, kỳ hạn tổng kết dựa vào xếp hạng điểm, xếp hạng trước sau phát thưởng. Sát thương càng cao, điểm càng nhiều\n\n6. Mỗi ngày người chơi có 5 lượt khiêu chiến, 0h mỗi ngày cài lại"}
