TAB_Describe[1948] = {"Bạo kích-Tăng tỷ lệ Bạo anh hùng\n\nKháng bạo-Giảm tỷ lệ bị bạo kích\n\nBạo thương-Tăng sát thương Bạo anh hùng\n\nKhống chế-Tăng tỷ lệ Khống chế\n\nKháng khống-Giảm tỷ lệ bị Khống chế\n\nChính xác-Tăng tỷ lệ Chính xác anh hùng\n\nNé-Tăng tỷ lệ Né anh hùng\n\nSát thương-Tăng sát thương anh hùng\n\nMiễn S.Thương-Giảm ST anh hùng phải chịu\n\nTrị liệu-Tăng hiệu quả Trị liệu anh hùng\n\nĐược trị liệu-Tăng hiệu quả được trị liệu anh hùng\n\nST Vật lý-Tăng ST vật lý anh hùng\n\nMiễn vật lý-Giảm ST vật lý anh hùng chịu\n\nST ma pháp-Tăng sát thương ma thuật anh hùng\n\nMiễn ma pháp-Giảm ST ma thuật của anh hùng phải chịu\n\nMiễn giảm bạo thương-Giảm sát thương bị bạo kích\n\n"}
