TAB_Describe[1954] = {"Quy tắc thưởng"}
TAB_Describe[1955] = {"1. Mỗi tuần tổ chức 3 trận Guild Chiến, lần lượt bắt đầu lúc 12:00 mỗi thứ 2, thứ 4, thứ 6\n\n2. Guild Lv3 trở lên và số người Sôi Nổi lớn hơn 5 mới được tham gia\n\n3. Bắt cặp Guild Chiến là bắt cặp Liên SV, bắt cặp 2 Guild thực lực gần kề làm đối thủ với nhau\n\n4. Khi bắt cặp xuất hiện đấu lượt trống (Bắt cặp không có đối thủ) không thể tham gia Guild Chiến lần này"}
TAB_Describe[1956] = {"1. Sau khi bắt đầu chiến đấu, thành viên Guild có thể chọn và khiêu chiến Cứ Điểm địch ở Trận Địa, khiêu chiến sẽ tốn 1 lượt khiêu chiến, trong Guild Chiến lần này mỗi người tham gia có 2 lượt khiêu chiến\n\n2. Trong Cứ Điểm địch có 3 độ khó (Dễ, Thường, Khó), độ khó càng cao thuộc tính chiến đấu địch càng cao (Hệ số độ khó hiển thị ở giao diện khiêu chiến), đồng thời thưởng khiêu chiến thành công, chiến tích, số sao càng cao\n\n3. Khiêu chiến Phế Khư Cứ Điểm đã bị công chiếm thành công không chỉ có thưởng khiêu chiến, còn tăng Buff Guild (Tăng thuộc tính cho Người Khiêu Chiến toàn Guild)\n\n4. Khiêu chiến Cứ Điểm thành công được nhận rất nhiều Chiến Tích, khiêu chiến Phế Khư thành công được nhận 5 điểm chiến tích, khiêu chiến thất bại cố định nhận 1 điểm chiến tích\n\n5. Guild Chiến duy trì 8h, lúc này sẽ thống kê số sao hai bên và phán định thắng thua (Người có số sao cao hơn thắng, cùng sao ai đạt trước sẽ thắng), đồng thời dựa vào kết quả trận đấu phát thưởng cho người tham gia và Guild tham gia"}
TAB_Describe[1957] = {"1. Thưởng khiêu chiến: Khiêu chiến Cứ Điểm được nhận thưởng, thưởng khiêu chiến thành công rất hậu hĩnh. Khiêu chiến thất bại cũng có thể nhận ít thưởng; Thưởng là Cống Hiến Guild, Vàng, nhận sau khi kết thúc khiêu chiến\n\n2. Thưởng chiến tích: Quyết định bởi xếp hạng chiến tích của thành viên trong Guild, xếp hạng càng cao thưởng càng hậu hĩnh, sau khi kết thúc Guild Chiến thưởng sẽ phát qua thư\n\n3. Thưởng kết quả: Dựa vào kết quả trận đấu phát thưởng cho người tham gia thắng thua hai bên, tất cả thành viên Guild bên thắng sẽ nhận Rương Cấp Cao tương ứng số người sôi nổi trong Guild, bên thua sẽ nhận Rương Thường!"}
