TAB_Describe[2013] = {"1. Vượt Tháp Vô Tận Tầng 400 mở Cung Hades\n\n2. Theo điều kiện cấp sao chỉnh đội hình khiêu chiến, có thể nhận 3 sao sau khi vượt ải\n\n3. Sau khi vượt ải 3 sao tầng này được càn quét\n\n4. Cứ 5 tầng được khiêu chiến Chủ Tháp, người chơi vượt ải lần đầu tự động thành Chủ Tháp, sau đó người chơi khiêu chiến thành công trở thành Chủ Tháp mới\n\n5. Đạt điều kiện tổng số sao được nhận thưởng\n\n6. Đạt điều kiện tổng số sao được mua vật phẩm hậu hĩnh ở Cửa Hàng\n\n7. Mỗi ngày miễn phí nhận 2 lượt khiêu chiến, khiêu chiến thất bại và khiêu chiến lần đầu mỗi tầng thắng lợi sẽ không tốn lượt"}
