TAB_Describe[2084] = {"1. Thời gian sự kiện, người chơi có thể hoàn thành nhiệm vụ nhận điểm, n\n2.từ đó tăng cấp Nổi Dậy, khi đạt cấp nhất định có thể \n\n3.nhận thưởng.\n\n4.2. Cấp Nổi Dậy có 2 loại thưởng tương ứng là “Anh Hùng” và “Vương Hầu”\n\n5. Người chơi “mở Vương Hầu” mới được nhận \n\n6.thưởng Vương Hầu Nổi Dậy.\n\n7.3. Trong thời gian mở SK người chơi có thể mua \n\n8.Quà Vương Hầu Nổi Dậy bất cứ lúc nào, và nhận \n\n9 tất cả thưởng Vương Hầu nổi dậy trước đây."}
TAB_Describe[2085] = {"1. Thời gian mở sự kiện: 17/9-30/9\n\n2.2. Sự kiện có tổng cộng 2 kỳ, ngày kết thúc mỗi kỳ lần lượt là 23/9\n\n3. và 30/9, 23:30-0h ngày tổng kết là thời gian nghỉ ngơi\n\n4. Người chơi không thể khiêu chiến.\n\n5.3. Khi mở sự kiện, dựa trên tình hình cụ thể của từng SV để phân cụm\n\n6. Tất cả thuộc tính của người chơi và quái trong mỗi cụm đều \n\n7tương đồng.\n\n8.4. Mỗi kỳ mở đồng thời 3 BOSS, người chơi có thể khiêu chiến đồng thời 3\n\n9 BOSS, mỗi BOSS có 5 độ khó {Dễ} {Thường}\n\n10. {Khó} {Địa ngục} {Vô tận}, vượt độ khó trước\n\n11. Có thể mở khóa độ khó tiếp theo.\n\n12.5 Khiêu chiến BOSS có cơ hội nhận vật phẩm sự kiện\n\n13. 6 Vật phẩm có thể dùng trong sự kiện.\n\n14. Khiêu chiến BOSS có thể nhận điểm, khi tổng kết dựa trên xếp hạng điểm\n\n15. Căn cứ xếp hạng để phát thưởng. Sát thương càng cao, điểm \n\n16.càng nhiều.\n\n17.7. Người chơi mỗi ngày có 5 lượt khiêu chiến, cài lại lúc 0h mỗi ngày.\n\n18.8. Mỗi lần tổng kết khiêu chiến, người chơi có thể chọn muốn trừ lượt khiêu chiến \n\n19.hay không, tính vào điểm hiện tại."}
TAB_Describe[2086] = {"1. Thời gian sự kiện, thông qua sự kiện Thí Luyện hoặc mua ở Tiệm \n\n2. Có thể nhận được vật phẩm sự kiện, cứ tốn 100 \n\n3.vật phẩm sự kiện, có thể tiến hành 1 lần lắc trứng\n\n4.2. Mỗi vòng có thể chọn 1 thưởng lớn cuối cùng đặt vào Kho Thưởng \n\n5. Trước khi mở được thưởng lớn, có thể tùy ý đổi thưởng lớn của vòng này!\n\n6.3. Trong một vòng, sau khi tiến hành lắc trứng 20 lần mới có cơ hội nhận được thưởng cuối cùng\n\n7. Sau đó mỗi lần lắc trứng đều sẽ tăng xác suất nhận thưởng lớn, lắc trứng 35 lần sẽ nhận được thưởng lớn cuối cùng!\n\n8.4. Thời gian sự kiện, mỗi này có thể đổi {Trứng Tinh Linh} 3 lần với giá giảm 60% Kim Cương\n\n9. Đổi {Trứng Tinh Linh} 5 lần với giá gốc, quá lượt sẽ không thể sử dụng Kim Cương để đổi.\n\n10.5. Nhận được thưởng lớn cuối cùng hoặc tất cả phần thưởng sau khi lắc trứng ở vòng hiện tại \n\n11. Có thể vào vòng tiếp theo\n\n12.6. Trứng Tinh Linh sẽ mất hiệu lực sau khi sự kiện kết thúc, hãy nhanh chóng sử dụng"}
TAB_Describe[2087] = {"1. Trong thời gian sự kiện, có thể tự chọn thưởng trên trang sự kiện để hoàn thành Đơn Ước Nguyện \n\n2.chu niên và sau khi Ước nguyện không thể đổi.\n\n3.2. Sau khi hoàn thành Đơn Ước Nguyện có thể tích lũy nhận 'Tinh Vận' \n\n4.khi treo máy chinh chiến trong thời gian sự kiện để đạt ước nguyện nhận thưởng.\n\n5.3. Ngày cuối cùng của sự kiện sẽ mở mua “Tinh Vận”\n\n6. Vật phẩm sẽ mất hiệu lực sau khi sự kiện kết thúc, hãy nhanh chóng sử dụng.\n\n7.4. Sau khi nhận thưởng Đơn Ước Nguyện xong có thể mua và nhận thưởng Đơn Ước Nguyện\n\n8. Thưởng “x5” (không bao gồm Khung AVA Chu Niên)."}
TAB_Describe[2088] = {"1. Nạp đơn trong ngày 60 Kim Cương trở lên có thể kích hoạt thưởng, mỗi ngày kích hoạt\n\n2. 1 lần\n\n3.2. 1 vòng có 15 mốc thưởng, nhận đủ 15 mốc thưởng tự động làm mới\n\n4. Sự kiện Nạp Liên Tục vòng 2\n\n5.3. Nạp thường, Quà Mua Trực Tiếp, Quỹ… có thể kích hoạt thưởng sự kiện này"}
