TAB_Describe[2094] = {"1. Mỗi kỳ Triệu Hồi Xuyên Không có một hoặc nhiều anh hùng up, lần đầu sẽ mặc định nhận một trong số đã chọn, sau đó bắt đầu rút thưởng, trong quá trình rút có thể tùy ý thay đổi anh hùng đã chọn\n\n2. Triệu Hồi Xuyên Không có thể rút được tất cả anh hùng trong Triệu Hồi Thứ Nguyên, đồng thời, tăng xác suất nhận Anh Hùng up đã chọn\n\n3. Trong Triệu Hồi Xuyên Không phe Khoa Học, Ma Pháp, Chiến Đấu cứ mỗi 50 lần triệu hồi chắc chắn nhận được anh hùng up đã chọn, phe Thần Ma cứ 70 lần triệu hồi sẽ nhận được anh hùng up đã chọn, phe Thần Ma hiếm cứ 120 lần triệu hồi sẽ nhận được anh hùng up đã chọn\n\n4. Khi nhận được anh hùng up đã chọn ở Triệu Hồi Xuyên Không, lượt chiêu mộ còn dư tối đa sẽ không được cài lại, khi đạt lượt chỉ định sẽ nhận được anh hùng đã chọn\n\n5. Nếu đổi anh hùng up giữa chừng, lượt triệu hồi còn lại sẽ dựa trên lượt triệu hồi đã tích lũy để thay đổi lượt tối thiểu tương ứng với anh dùng đã chọn\n\n6. Nếu lượt triệu hồi tích lũy đổi lớn hơn hoặc bằng lượt tối thiểu sau khi đổi, lần triệu hồi sau sẽ nhận được anh hùng up\n\n7. Sau khi lượt Kim Cương mỗi ngày đạt giới hạn, không thể tiếp tục sử dụng Kim Cương để triệu hồi, lượt triệu hồi Lệnh Triệu Hồi Xuyên Không không giới hạn"}
