TAB_Describe[2102] = {"1. Giải Đấu Võ Đạo sẽ mở vào lúc 00:00 ngày thứ 7 đến 23:00 CN hàng tuần.\n\n2. Người chơi Top 100 trong đấu trường server này mới được tham gia khiêu chiến\n\n3. Thắng đối thủ có thứ hạng cao hơn sẽ được hoán đổi thứ hạng với người đó, thất bại thứ hạng không đổi\n\n4. Mỗi lần phát động chiến đấu sẽ tốn 1 lượt khiêu chiến, lượt khiêu chiến làm mới vào 00:00 mỗi ngày\n\n5. Khi người chơi có xếp hạng khiêu chiến >400 nhấp nút Khiêu chiến nhanh, tự động bỏ qua chiến đấu"}
TAB_Describe[2103] = {"1. 23:00 CN dựa trên thứ hạng trong ngày để phát thưởng, xem chi tiết trong giao diện thưởng\n\n2. Mỗi ngày đều có thể hâm mộ Top3 người chơi trong Vương Giả Võ Đạo để nhận thưởng điểm Võ Đạo\n\n3. Điểm Võ Đạo có thể dùng để đổi vật phẩm hiếm trong Cửa Hàng Điểm"}
TAB_Describe[2104] = {"1. Nếu chiến đấu quá giờ thì xem như khiêu chiến thất bại\n\n2. Có thể xem và chia sẻ lịch sử chiến đấu của mình ở Chiến báo, hoặc xem Chiến báo của người khác để học cách sắp xếp đội hình của các đại thần\n\n3. Không thể phát động chiến đấu với đối thủ đang bị khiêu chiến."}
