TAB_Describe[2107] = {"1. Trong thời gian sự kiện, có thể tự chọn thưởng hoàn thành Đơn Ước Nguyện chu niên trên giao diện sự kiện, sau khi ước nguyện không thể đổi\n2. Sau khi hoàn thành Đơn Ước Nguyện có thể treo máy chiến đấu tích lũy '%s' đủ điều kiện nhận thưởng ước nguyện\n3. Ngày cuối cùng sự kiện mở mua “%s”, vật phẩm sự kiện sẽ mất hiệu lực sau khi sự kiện kết thúc, hãy nhanh chóng sử dụng\n4. Sau khi nhận thưởng Đơn Ước Nguyện có thể mua và nhận thưởng Đơn Ước Nguyện x5 (không bao gồm Khung AVA Chu Niên)"}
