TAB_Describe[2114] = {"1. Thời gian sự kiện, có thể hoàn thành nhiệm vụ nhận điểm để tăng cấp Nổi Dậy, khi đạt cấp nhất định có thể nhận thưởng\n\n2. Cấp Nổi Dậy có hai loại Thưởng Nổi Dậy “Anh Hùng” và “Vương Giả”, “Mở Khóa Vương Giả” mới có thể nhận thưởng Vương Giả Nổi Dậy\n\n3. Có thể mua Quà Vương Giả Nổi Dậy bất cứ lúc nào trong thời gian sự kiện, và nhận được tất cả thưởng Vương Giả Nổi Dậy bao gồm thưởng cấp trước đó."}
