TAB_Describe[2348] = {"#C(#40404B)1. Người chơi đạt Lv#C(#1A954A)85#C(#40404B), và từ ngày thứ #C(#1A954A)31#C(#40404B) mở Sv có thể tham gia Giải Guild Anh Hùng."}
TAB_Describe[2349] = {"#C(#40404B)1. Chiến đấu #C(#1A954A)vòng tròn#C(#40404B), mỗi trận duy trì #C(#1A954A)30#C(#40404B) lượt, sau khi diệt đối thủ, HP sẽ không được làm mới, phe thắng #C(#1A954A)kế thừa HP#C(#40404B) tiến vào trận tiếp theo, đến khi một phe tiêu diệt toàn bộ Anh Hùng phe kia mới được tính chiến thắng."}
TAB_Describe[2350] = {"#C(#40404B)1. Tổ đội và khiêu chiến sẽ đóng vào #C(#1A954A)23:00#C(#40404B) mỗi CN và tiến hành tổng kết mùa giải, chính thức tổng kết và phát thưởng vào #C(#1A954A)23:30#C(#40404B) mỗi CN."}
TAB_Describe[2351] = {"Giải Guild Anh Hùng"}
TAB_Describe[2352] = {"Sẽ mở khóa sau, vui lòng chờ"}
TAB_Describe[2353] = {"Kết duyên"}
TAB_Describe[2354] = {"Sổ Tay"}
TAB_Describe[2355] = {"Xem"}
TAB_Describe[2356] = {"#C(#40404B)2. Giải Guild Anh Hùng chia thành 4 giai đoạn, giai đoạn 1 là #C(#1A954A)giai đoạn đình chiến#C(#40404B), giai đoạn 2 là #C(#1A954A)giai đoạn tổ đội#C(#40404B), giai đoạn 3 là #C(#1A954A)giai đoạn đối chiến#C(#40404B), giai đoạn 4 là #C(#1A954A)giai đoạn tổng kết#C(#40404B)."}
TAB_Describe[2357] = {"#C(#40404B)3. Trong Giải Guild Anh Hùng, có thể #C(#1A954A)khiêu chiến đội chơi khác#C(#40404B), để tăng điểm cho bản thân. Sau khi tiến vào Đấu Trường, người chơi có thể #C(#1A954A)chọn 1 đội để gia nhập#C(#40404B), cũng có thể tổ đội #C(#1A954A)mời người chơi khác gia nhập#C(#40404B). Chỉ có thể tổ đội với người chơi cùng server."}
TAB_Describe[2358] = {"#C(#40404B)4. Thứ #C(#1A954A)6#C(#40404B) mỗi tuần là giai đoạn tổ đội, mở tính năng tổ đội. Sau khi lập đội, ban đầu có #C(#1A954A)10#C(#40404B) lượt khiêu chiến, mỗi lần khiêu chiến tốn #C(#1A954A)1#C(#40404B) lượt, #C(#1A954A)2#C(#40404B) tiếng khôi phục 1 lần, tối đa có #C(#1A954A)6#C(#40404B) lượt, không thể khiêu chiến khi lượt khiêu chiến bằng #C(#1A954A)0#C(#40404B)."}
TAB_Describe[2359] = {"#C(#40404B)5. Đội trưởng quyết định thứ tự ra trận và chọn đội khiêu chiến. Đội trưởng có thể cho phép thành viên khiêu chiến khi bản thân offline, cũng có thể tự phát động khiêu chiến. Nếu đội trưởng không cho phép thành viên khiêu chiến khi bản thân offline, thì thành viên chỉ có thể xem lịch sử chiến đấu."}
TAB_Describe[2360] = {"#C(#40404B)6. Mỗi người chơi tham gia tổ đội ít nhất cần cho 1 anh hùng ra trận, người chơi có thể điều chỉnh đội hình của mình mọi lúc."}
TAB_Describe[2361] = {"#C(#40404B)2. Tiến hành tổng kết điểm sau khi chiến đấu, thắng được nhận điểm, khiêu chiến thất bại không mất điểm.\n\n3. Sau 1 trận, nếu trong lượt chưa thể đánh bại đối thủ, thì phe thủ giành thắng lợi, kế thừa HP tiến vào trận tiếp theo."}
TAB_Describe[2362] = {"#C(#40404B)2. Sau khi bắt đầu đến trước khi kết thúc mùa giải, thành viên và đội trưởng đều được nhận thưởng lượt khiêu chiến. Sau khi tổng kết, thưởng lượt khiêu chiến chưa nhận sẽ phát qua thư."}
TAB_Describe[2363] = {"#C(#40404B)3. Sau khi mùa giải kết thúc, sẽ phát thưởng dựa trên thứ hạng qua thư."}
TAB_Describe[2364] = {"#C(#40404B)4. Điểm thưởng có thể dùng để đổi lượng lớn vật phẩm thưởng trong tiệm."}
