TAB_Describe[2432] = {"Viện Quân sẽ ra trận vào lượt sau sau khi anh hùng đã ra trận phe ta tử vong.\n\nCấp sao của Viện Quân càng cao, hiệu quả buff của toàn quân càng mạnh (trạng thái này không bị thanh tẩy)\n\nViện Quân 5 sao-toàn thể tăng 1% công, duy trì 2 lượt\nViện quân 6 sao-toàn thể tăng 2% công, duy trì 2 lượt\nViện Quân 7 sao-toàn thể tăng 3% công, duy trì 2 lượt\nViện Quân 8 sao-toàn thể tăng 4% công, duy trì 2 lượt\nViện Quân 9 sao-toàn thể tăng 5% công, duy trì 2 lượt\nViện Quân 10 sao-toàn thể tăng 6% công, duy trì 2 lượt\nViện Quân 11 sao-toàn thể tăng 7% công, duy trì 2 lượt\nViện Quân 12 sao-toàn thể tăng 8% công, duy trì 2 lượt\nViện Quân 13 sao-toàn thể tăng 9% công, duy trì 2 lượt"}
