TAB_Describe[2553] = {"Quy trình Tranh Đoạt Bleach"}
TAB_Describe[2554] = {"#C(#40404B)1. Tranh Đoạt Bleach có lối chơi PvP Liên SV, cấp người chơi đạt Lv#C(#1A954A)65#C(#40404B), và từ ngày thứ #C(#1A954A)15#C(#40404B) mở server có thể tham gia Tranh Đoạt Bleach."}
TAB_Describe[2555] = {"#C(#40404B)2. Tranh Đoạt Bleach sẽ mở báo danh vào #C(#1A954A)00:00-24:00 mỗi thứ 6#C(#40404B), người chơi chưa báo danh không thể tham gia."}
TAB_Describe[2556] = {"#C(#40404B)3. Lối chơi hoàn chỉnh trong 1 mùa kéo dài #C(#1A954A)3 ngày (thứ 6, 7, CN)#C(#40404B), lối chơi chia thành #C(#1A954A)giai đoạn báo danh→ giai đoạn bắt cặp→ giai đoạn chuẩn bị→ giai đoạn thực hiện→ giai đoạn chiến đấu#C(#40404B)."}
TAB_Describe[2557] = {"#C(#40404B)4. Người chơi chưa báo danh không thể tham chiến, nhưng có thể xem quá trình chiến đấu, cũng có thể dự đoán."}
TAB_Describe[2558] = {"Quy tắc bắt cặp và chiến đấu"}
TAB_Describe[2559] = {"#C(#40404B)1. Sau khi giai đoạn báo danh kết thúc, dựa trên #C(#1A954A)điểm trung bình lực chiến của người chơi báo danh#C(#40404B) ở server này để bắt cặp với server có lực chiến tương đương."}
TAB_Describe[2560] = {"#C(#40404B)2. Sau khi bắt cặp đối thủ sẽ tiến vào giai đoạn chuẩn bị. Ở giai đoạn này, người chơi có thể dựng chiến thuật dựa trên thực lực người chơi báo danh ở server này, chọn lộ trình hợp lý"}
TAB_Describe[2561] = {"#C(#40404B)3. Sau khi kết thúc giai đoạn chuẩn bị sẽ tiến vào giai đoạn thực hiện. Lúc này người chơi #C(#1A954A)không thể thay đổi đội hình ra trận đã bày trước đó, cũng không thể đổi lộ trình#C(#40404B). Nếu đổi đội hình vào lúc này, thì sẽ có hiệu lực trong lối chơi kỳ sau. Giai đoạn thực hiện có thể nhận được rất nhiều #C(#1A954A)thưởng sự kiện#C(#40404B)."}
TAB_Describe[2562] = {"#C(#40404B)4. Giai đoạn chiến đấu, tiến hành đấu luân phiên trên lộ trình đã chọn dựa trên đội mà người chơi phái ra. Sau khi cả 3 lộ trình chiến đấu đều kết thúc, sẽ phát thưởng qua thư."}
TAB_Describe[2563] = {"Hướng dẫn quy tắc đặc thù"}
TAB_Describe[2564] = {"#C(#40404B)1. Tranh Đoạt Bleach chia thành 3 lộ trình xuất binh, #C(#1A954A)tiêu diệt tất cả địch trong cùng lộ trình#C(#40404B) được tính là chiến thắng ở lộ trình đó. Nếu #C(#1A954A)tiêu diệt đối thủ ở 2 lộ trình trở lên#C(#40404B), thì sẽ giành chiến thắng ở server đó."}
TAB_Describe[2565] = {"#C(#40404B)2. Chiến đấu theo kiểu #C(#1A954A)đấu luân phiên#C(#40404B), mỗi trận duy trì 22 lượt, sau khi tiêu diệt đối thủ, giữ HP tiến vào trận tiếp theo."}
TAB_Describe[2566] = {"#C(#40404B)3. Mỗi đội của người chơi đều có #C(#1A954A)5#C(#40404B) điểm thể lực, mỗi trận tốn 1 điểm thể lực. Khi điểm thể lực bằng 0, dù thắng hay thua cũng thoát khỏi trận chiến."}
TAB_Describe[2567] = {"#C(#40404B)4. Nếu 2 bên đều không có đội còn sống, lộ trình chiến đấu này được tính hòa."}
TAB_Describe[2568] = {"Quy tắc thưởng"}
TAB_Describe[2569] = {"#C(#40404B)Thưởng được tạo thành từ ba phần sau, phát vào 20h chủ nhật"}
TAB_Describe[2570] = {"#C(#40404B)1. #C(#1A954A)Thưởng lộ trình#C(#40404B): người chơi server này giành #C(#1A954A)chiến thắng#C(#40404B) trên 1 lộ trình, thì tất cả người chơi báo danh đều được nhận #C(#1A954A)1500#C(#40404B) điểm thưởng xu. Cứ có 1 lộ trình #C(#1A954A)thất bại hoặc hòa#C(#40404B), thì được nhận #C(#1A954A)300#C(#40404B) điểm thưởng xu. Thắng càng nhiều lộ trình, thưởng nhận được sẽ càng nhiều."}
TAB_Describe[2571] = {"#C(#40404B)2. #C(#1A954A)Thưởng tiêu diệt địch#C(#40404B): phát thưởng tiêu diệt địch tương ứng với số lượng địch mà người chơi đã tiêu diệt. Tiêu diệt càng nhiều thưởng càng phong phú."}
TAB_Describe[2572] = {"#C(#40404B)3. #C(#1A954A)Thưởng dự đoán#C(#40404B): Giai đoạn chiến đấu, người chơi có thể dự đoán thắng thua của người chơi trong trận. Đá Hư Linh Hồn Giới nhận được sẽ chuyển thành thưởng xu khi tổng kết, và sẽ phát qua thư."}
