TAB_Describe[2605] = {"Thám hiểm sẽ ưu tiên dùng Chìa Khóa Kho Báu, Thám hiểm Kim Cương giới hạn mỗi ngày %s lần, dùng Kim Cương ưu đãi 10 lần giảm 10%%"}
