TAB_Describe[2608] = {"#C(#40404B)1. Mỗi lần khiêu chiến đều tốn #C(#1A954A)1#C(#40404B) lượt khiêu chiến, khiêu chiến thất bại #C(#1A954A)không mất#C(#40404B) lượt."}
TAB_Describe[2609] = {"#C(#40404B)2. Sau khi #C(#1A954A)hoàn thành mục tiêu 3 sao#C(#40404B) ở mỗi ải sẽ mở tính năng #C(#1A954A)càn quét#C(#40404B) tương ứng, mỗi lần càn quét tốn 1 lượt khiêu chiến."}
TAB_Describe[2610] = {"#C(#40404B)3. Lượt khiêu chiến được cài lại vào #C(#1A954A)0h#C(#40404B) mỗi ngày. Mỗi ngày có thể dùng Kim Cương mua #C(#1A954A)2#C(#40404B) lượt khiêu chiến."}
TAB_Describe[2611] = {"#C(#40404B)4. Cần vượt tất cả ải chương trước mới mở chương tiếp theo."}
TAB_Describe[2612] = {"#C(#40404B)5. Ải thứ #C(#1A954A)10#C(#40404B) mỗi chương là #C(#1A954A)ải Boss#C(#40404B). Ải Boss có #C(#1A954A)2 đội địch#C(#40404B), cần tiêu diệt tất cả mới có thể vượt ải."}
TAB_Describe[2613] = {"#C(#40404B)6. Một số chương cần các chương khác đạt số lượng mục tiêu cấp sao chỉ định để mở."}
TAB_Describe[2614] = {"#C(#40404B)7. Hoàn thành mục tiêu cấp sao ở mỗi chương được nhận thưởng Bảo Khí chỉ định."}
TAB_Describe[2615] = {"#C(#40404B)1. Bảo Khí mở khi cấp người chơi đạt Lv#C(#1A954A)105#C(#40404B) và cấp Thế Giới đạt Lv#C(#1A954A)110#C(#40404B), hoặc cấp người chơi đạt Lv#C(#1A954A)110#C(#40404B). Khi anh hùng đạt #C(#1A954A)6 sao#C(#40404B), mở mang Bảo Khí cho anh hùng này."}
TAB_Describe[2616] = {"#C(#40404B)2. Mỗi Bảo Khí chia thành #C(#1A954A)Thường, Ưu Tú, Hoàn Mỹ#C(#40404B), lần lượt tương ứng với 0-2 thuộc tính ngẫu nhiên."}
TAB_Describe[2617] = {"#C(#40404B)3. Mang cùng lúc bộ Bảo Khí cùng tên và cấp sao mới có thể kích hoạt hiệu quả bộ đồ. 2 bộ và 4 bộ lần lượt có thể kích hoạt hiệu quả bộ đồ tương ứng."}
TAB_Describe[2618] = {"#C(#40404B)4. Bảo Khí Ưu Tú và Hoàn Mỹ có thể tẩy luyện, tẩy luyện có thể thay đổi loại hình và trị số thuộc tính ngẫu nhiên của Bảo Khí, khi mỗi Bảo Khí tẩy luyện đến lượt nhất định, thuộc tính sẽ đạt giá trị tối đa."}
TAB_Describe[2619] = {"#C(#40404B)5. Có thể nhận Bảo Khí ở #C(#1A954A)Trận Chiến Chén Thánh, Cửa Hàng Bảo Khí, Kho Báu Đế Vương#C(#40404B)."}
TAB_Describe[2620] = {"#C(#40404B)6. Sau khi bán Bảo Khí có thể nhận #C(#1A954A)Đá Tẩy Luyện#C(#40404B), Đá Tẩy Luyện có thể dùng để tẩy luyện Bảo Khí."}
