TAB_Describe[2743] = {"#C(#40404B)1. Bảo Khí phẩm #C(#1A954A)Ưu Tú#C(#40404B) và #C(#1A954A)Hoàn Mỹ#C(#40404B) có thể tẩy luyện, sau khi tẩy luyện có thể thay đổi #C(#1A954A)loại hình#C(#40404B) và #C(#1A954A)trị số#C(#40404B) thuộc tính ngẫu nhiên."}
TAB_Describe[2744] = {"#C(#40404B)2. Thuộc tính tẩy luyện chỉ tăng chứ không giảm, sau khi 1 Bảo Khí đạt lượt tẩy luyện nhất định, trị số thuộc tính này sẽ đạt giới hạn."}
TAB_Describe[2745] = {"#C(#40404B)3. Khi tẩy luyện Bảo Khí có thể khóa thuộc tính. Sau khi khóa, tiến hành tẩy luyện tiếp sẽ chỉ thay đổi #C(#1A954A)trị số#C(#40404B) thuộc tính, không thay đổi #C(#1A954A)loại hình#C(#40404B) thuộc tính"}
TAB_Describe[2746] = {"#C(#40404B)1. Bảo Khí có cùng loại, phẩm, cấp sao, vị trí có thể ghép thành Bảo Khí #C(#1A954A)1#C(#40404B) sao cao."}
TAB_Describe[2747] = {"#C(#40404B)2. Sau khi ghép, thuộc tính cố định của Bảo Khí tăng thành thuộc tính sao cao, thuộc tính ngẫu nhiên khi ghép có thể tự chủ chọn thuộc tính cần lưu lại. "}
TAB_Describe[2748] = {"#C(#40404B)3. Sau khi ghép Bảo Khí, có thể kế thừa lượt tẩy luyện ban đầu."}
TAB_Describe[2749] = {"#C(#40404B)4. Khi bán Bảo Khí, vật liệu tẩy luyện sẽ được hoàn trả 100% dựa trên lượt tẩy luyện."}
TAB_Describe[2750] = {"#C(#40404B)5. Ghép Bảo Khí tạm thời mở ghép đến Bảo Khí 4 sao."}
