TAB_Describe[2848] = {"Hiệu quả bảo hộ: tấn công +5%, thủ +5%"}
TAB_Describe[2849] = {"1. Đấu Trường Toàn Dân là mô hình thi đấu công bằng, trong cùng 1 bậc, anh hùng ra trận của người chơi sẽ thống nhất cấp và cấp sao\n2. Mỗi anh hùng sẽ kết hợp kỹ năng thiên phú mặc định, khi cấp sao của anh hùng tăng, số lượng và cấp thiên phú cũng tăng theo\n3. Trong Đấu Trường Toàn Dân chỉ có Thần Khí có hiệu lực, cấp và thuộc tính đồng nhất, những Dưỡng khác không có hiệu lực"}
TAB_Describe[2850] = {"1. Mỗi trận có 20 lượt, khi đạt bậc tương đối cao sẽ mở khóa đội 2 và đội 3, hình thức chiến đấu sau đó đổi thành đấu luân phiên (kế thừa HP và thứ tự thi triển kỹ năng sau khi trận trước kết thúc)\n2. Sau khi lượt chiến đấu đạt giới hạn, nếu hai bên không phân thắng bại, thì người chơi có sát thương cao hơn chiến thắng\n3. Bắt cặp cùng bậc để chiến đấu, thắng cộng điểm, thua trừ điểm, điểm của người chơi được bắt cặp cũng sẽ thay đổi tương ứng\n4. Khi bậc hiện tại không có đối thủ khác, sẽ bắt cặp với đối thủ liên bậc để tiến hành chiến đấu\n5. Thua liên tiếp 3 trận sẽ phát động tăng buff thua cuộc, công và thủ tăng 5%"}
TAB_Describe[2851] = {"#C(#1A954A)Đồng Bậc I: Anh Hùng 5 sao; Thần Khí Lv10, kỹ năng Thần Khí Lv4, Tinh Luyện Thần Khí Lv10\nĐồng Bậc II: Anh Hùng 6 sao; Thần Khí Lv15, kỹ năng Thần Khí Lv5, Tinh Luyện Thần Khí Lv30\nĐồng Bậc III: Anh Hùng 7 sao; Thần Khí Lv20, kỹ năng Thần Khí Lv6, Tinh Luyện Thần Khí Lv50\nBạc Bậc I: Anh Hùng 8 sao; Thần Khí Lv25, kỹ năng Thần Khí Lv7, Tinh Luyện Thần Khí Lv70\nBạc Bậc III: Anh Hùng 9 sao; Thần Khí Lv30, kỹ năng Thần Khí Lv8, Tinh Luyện Thần Khí Lv90\nBậc Vàng: Anh Hùng 10 sao; Thần Khí Lv40, kỹ năng Thần Khí Lv9, Tinh Luyện Thần Khí Lv120\nBậc Bạch Kim: Anh Hùng 11 sao; Thần Khí Lv50, kỹ năng Thần Khí Lv10, Tinh Luyện Thần Khí Lv150\nBậc Kim Cương: Anh Hùng 12 sao; Thần Khí Lv60, kỹ năng Thần Khí Lv11, Tinh Luyện Thần Khí Lv180\nBậc Vương Giả: Anh Hùng 13 sao; Thần Khí Lv70, kỹ năng Thần Khí Lv12, Tinh Luyện Thần Khí Lv210"}
TAB_Describe[2852] = {"1. Hoàn thành nhiệm vụ khiêu chiến mỗi ngày được nhận thưởng mỗi ngày\n2. Lần đầu đạt bậc chỉ định được nhận thưởng lần đầu đạt\n3. Khi mùa giải kết thúc, phát thưởng xếp hạng dựa trên tỉ lệ xếp hạng"}
