TAB_Describe[2922] = {"Đỉnh Cao"}
TAB_Describe[2923] = {"Duy trì thứ hạng trong chung kết Giải Đỉnh Cao được nhận thưởng sau:"}
TAB_Describe[2924] = {"#C(#FFFFFF)Giải Đỉnh Cao còn: #C(#00FF10)%s"}
TAB_Describe[2925] = {"%ss sau được làm mới"}
TAB_Describe[2926] = {"Like mỗi ngày được nhận thưởng điểm Giải Đấu Bậc"}
TAB_Describe[2927] = {"Thưởng bậc"}
TAB_Describe[2928] = {"Sau khi lần đầu đạt bậc tương ứng ở mỗi mùa giải được nhận thủ công"}
TAB_Describe[2929] = {"Nửa đầu và cuối mùa giải sẽ tổng kết và phát thưởng bậc 1 lần"}
