TAB_Describe[2932] = {"Thưởng thành tựu được cài lại vào mỗi mùa giải"}
TAB_Describe[2933] = {"Số trận thắng Giải Thường Niên hiện tại: %s"}
TAB_Describe[2934] = {"Mở khóa Lệnh Ma Vương"}
TAB_Describe[2935] = {"Số trận thắng"}
TAB_Describe[2936] = {"Thưởng Thường Niên"}
TAB_Describe[2937] = {"Thưởng Thêm"}
TAB_Describe[2938] = {"Thắng Giải Đỉnh Cao %s lần (%s/%s)"}
TAB_Describe[2939] = {"Trở lại Giải Đỉnh Cao"}
TAB_Describe[2940] = {"Có 1 Ấn Ký V đã mở. Có thể nhận bằng cách ghép Ấn Ký"}
TAB_Describe[2941] = {"#C(#40404B)1. Ấn Ký V có thể tiến bậc thành Ấn Ký VI bằng cách tôi luyện"}
TAB_Describe[2942] = {"#C(#40404B)2. Thuộc tính cố định của Ấn Ký VI #C(#1A954A)gấp đôi#C(#40404B) Ấn Ký V, và nhiều hơn #C(#1A954A)1#C(#40404B) dòng tỉ lệ thuộc tính, kèm cấp kỹ năng Ấn Ký #C(#1A954A)+1"}
TAB_Describe[2943] = {"#C(#40404B)3. Trong quá trình tôi luyện Ấn Ký V #C(#1A954A)không thể tiến hành đúc lại#C(#40404B), sau khi trở thành Ấn Ký VI mới có thể tiếp tục đúc lại"}
TAB_Describe[2944] = {"Hãy đặt Ấn Ký chờ tôi luyện"}
TAB_Describe[2945] = {"Chọn 3 viên Ma Thạch, thưởng sẽ phát qua thư vào 0h"}
TAB_Describe[2946] = {"Mang cho anh hùng: %s"}
TAB_Describe[2947] = {"Giải Đỉnh Cao sắp bắt đầu! Ai sẽ bước lên đỉnh cao vinh quang, tham gia thi đấu và dự đoán thú vị có thể nhận thưởng phong phú!"}
TAB_Describe[2948] = {"Kỹ năng Ấn Ký chưa lưu trong quá trình tôi luyện sẽ biến mất, trong quá trình tôi luyện không thể tiến hành đúc lại. Sau khi trở thành Ấn Ký VI mới có thể tiếp tục đúc lại"}
TAB_Describe[2949] = {"Tin Đồn Lì Xì"}
TAB_Describe[2950] = {"Lướt sang hai bên có thể đổi Lì Xì"}
TAB_Describe[2951] = {"%s giành chức quán quân trong Giải Đỉnh Cao, khắp nơi chúc mừng"}
TAB_Describe[2952] = {"#C(#1A954A)%s#C(#40404B) mở Lì Xì nhận"}
TAB_Describe[2953] = {"Đấu Top 128"}
TAB_Describe[2954] = {"Mở rương được nhận ngẫu nhiên 1 vật phẩm sau"}
TAB_Describe[2955] = {"Tăng cấp rương"}
TAB_Describe[2956] = {"Rương Dũng Sĩ"}
TAB_Describe[2957] = {"Rương Đế Vương có thể nhận hôm nay: "}
TAB_Describe[2958] = {"Sau khi nâng cấp Rương, Rương Đế Vương phát qua thư vào 0h hôm sau"}
TAB_Describe[2959] = {"Xem trước thưởng"}
TAB_Describe[2960] = {"Hướng dẫn tăng cấp"}
TAB_Describe[2961] = {"1. Nâng cấp rương có thể mở khóa Rương Đế Vương; sau đó sẽ phát qua thư vào 0h mỗi ngày tùy theo mức hoàn thành nhiệm vụ của ngày hôm trước, thưởng số lượng Rương Đế Vương tương ứng;"}
TAB_Describe[2962] = {"2. Khi tăng cấp Rương, ngoài nhận được số Kim Cương tương ứng ở mốc đó, thưởng của Rương Đế Vương đã hoàn thành nhiệm vụ trước đó cũng được hoàn trả ngay."}
TAB_Describe[2963] = {"Quy trình Giải Bậc Chí Tôn"}
TAB_Describe[2964] = {"#C(#40404B)1. Giải Bậc Chí Tôn là lối chơi PvP liên server, người chơi đạt #C(#1A954A)Lv100#C(#40404B) và cấp thế giới đạt #C(#1A954A)Lv100#C(#40404B) có thể tham gia, hoặc người chơi phải đạt #C(#1A954A)Lv105#C(#40404B) không bị giới hạn cấp thế giới."}
TAB_Describe[2965] = {"#C(#40404B)2. Giải Bậc Chí Tôn sẽ bắt đầu bắt cặp vào #C(#1A954A)00:00-23:30#C(#40404B) mỗi ngày, không thể khiêu chiến vào nửa tiếng cuối ngày, hãy chú ý."}
TAB_Describe[2966] = {"#C(#40404B)3. Một mùa giải hoàn chỉnh có #C(#1A954A)21 ngày#C(#40404B), sau khi mùa giải kết thúc sẽ lập tức tổng kết và mở mùa giải tiếp theo. Mỗi mùa giải chia thành 2 giai đoạn #C(#1A954A)nửa đầu mùa giải#C(#40404B) và #C(#1A954A)nửa cuối mùa giải#C(#40404B), nửa đầu mùa giải kết thúc lập tức mở nửa cuối mùa giải."}
TAB_Describe[2967] = {"#C(#40404B)4. Khi mỗi mùa giải bắt đầu, hệ thống sẽ dựa trên tình hình các server để chia thành nhiều khu đấu."}
TAB_Describe[2968] = {"Quy tắc bắt cặp và chiến đấu"}
TAB_Describe[2969] = {"#C(#40404B)1. Mỗi ngày người chơi có #C(#1A954A)3 lần#C(#40404B) bắt cặp miễn phí, bắt cặp chiến đấu 1 lần tốn 1 lượt, người chơi Vip có thể mua thêm lượt bắt cặp mỗi ngày, tối đa được mua #C(#1A954A)10 lần#C(#40404B), cài lại vào 0h."}
TAB_Describe[2970] = {"#C(#40404B)2. Sau khi thắng trận được nhận #C(#1A954A)EXP bậc#C(#40404B) và #C(#1A954A)thưởng thắng trận#C(#40404B), bậc càng cao, thưởng nhận thêm càng nhiều. Chiến đấu thất bại sẽ bị trừ EXP bậc, đồng thời cũng nhận được một ít thưởng."}
TAB_Describe[2971] = {"Về Giải Đỉnh Cao"}
TAB_Describe[2972] = {"#C(#40404B)1. Giải Đỉnh Cao sẽ mở vào #C(#1A954A)3 ngày#C(#40404B) cuối cùng của mùa giải, chia thành 2 giai đoạn. 2 ngày đầu là Vòng Loại, ngày cuối cùng là Chung Kết."}
TAB_Describe[2973] = {"Quy tắc bậc"}
TAB_Describe[2974] = {"#C(#40404B)1. Thắng trận được nhận EXP bậc, lực chiến và bậc của đối thủ càng cao, EXP bậc nhận được càng cao. Sau khi EXP bậc đầy sẽ tiến vào giai đoạn Đấu Tăng Bậc."}
TAB_Describe[2975] = {"#C(#40404B)2. Trong Đấu Tăng Bậc, người chơi có thể tăng bậc sau khi thắng số lượt nhất định, dưới bậc Bạch Kim (gồm bậc Bạch Kim) nếu #C(#1A954A)“1 trận thắng 1”#C(#40404B) sẽ được tăng bậc, trên bậc Bạch Kim cần #C(#1A954A)“3 trận thắng 2”#C(#40404B) mới có thể tăng bậc."}
TAB_Describe[2976] = {"#C(#40404B)3. Nếu người chơi chưa đạt số trận thắng chỉ định trong Đấu Tăng Bậc, thì tăng bậc thất bại, bậc không đổi và sẽ bị trừ một lượng EXP bậc nhất định."}
TAB_Describe[2977] = {"#C(#40404B)4. Khi người chơi lần đầu tăng đến bậc nào đó trong mùa giải này, có thể nhận #C(#1A954A)thưởng bậc lần đầu đạt#C(#40404B), mỗi bậc chỉ được nhận thưởng này 1 lần. Bậc ban đầu không có thưởng bậc lần đầu đạt."}
TAB_Describe[2978] = {"#C(#40404B)5. Khi EXP bậc hiện tại của người chơi nhỏ hơn 0, bậc sẽ không lập tức giảm mà sẽ ưu tiên trừ EXP hòa hoãn. Khi EXP hòa hoãn không đủ, bậc sẽ bị giảm."}
TAB_Describe[2979] = {"Tổng kết mùa giải"}
TAB_Describe[2980] = {"#C(#40404B)1. Khi nửa đầu và nửa cuối mùa giải kết thúc, sẽ lần lượt phát #C(#1A954A)thưởng tổng kết bậc#C(#40404B) 1 lần."}
TAB_Describe[2981] = {"#C(#40404B)2. Sau khi cả mùa giải kết thúc, người chơi đạt bậc #C(#1A954A)“Cường Giả Chí Tôn”#C(#40404B) và xếp trong #C(#1A954A)Top 6#C(#40404B) được nhận #C(#1A954A)tôn hiệu Cường Lực#C(#40404B) (BXH tiến hành xếp hạng dựa trên bậc và điểm), tôn hiệu sau khi được kích hoạt sẽ duy trì toàn mùa giải."}
TAB_Describe[2982] = {"#C(#40404B)3. Khi nửa đầu mùa giải kết thúc sẽ chỉ phát thưởng tổng kết bậc, không cài lại bậc và xếp hạng. Khi nửa cuối mùa giải kết thúc (tức cả mùa giải kết thúc), sẽ cài lại xếp hạng, và dựa trên bậc hiện tại để quyết định #C(#1A954A)bậc kế thừa#C(#40404B) của mùa giải mới. Có thể xem quy tắc kế thừa tại #C(#1A954A){Xem bậc}#C(#40404B)."}
TAB_Describe[2983] = {"#C(#40404B)4. Sau khi mỗi mùa giải kết thúc, hệ thống sẽ ghi lại người chơi trong #C(#1A954A)Top 6#C(#40404B). Có thể xem ở #C(#1A954A){Huyền Thoại Mùa Giải}#C(#40404B)."}
TAB_Describe[2984] = {"Bạn có nhân vật Lv%s trở lên ở khu khác, xác nhận bỏ qua hướng dẫn tân thủ?"}
