TAB_Describe[3041] = {"Mua %s"}
TAB_Describe[3042] = {"Được nhận thưởng khi Cung Hades nhận số sao chỉ định"}
TAB_Describe[3043] = {"Số sao hiện tại"}
TAB_Describe[3044] = {"Tiến bậc %s nhận"}
TAB_Describe[3045] = {"#C(#40404B)2. Người chơi đạt bậc #C(#1A954A)“Bạch Kim Ⅰ”#C(#40404B) trong Giải Thường Niên sẽ tiến vào Giải Đỉnh Cao (Vòng Loại), người chơi đạt bậc #C(#1A954A)“Bạch Kim Ⅰ”#C(#40404B) trong Vòng Loại cũng có thể tham gia Vòng Loại."}
TAB_Describe[3046] = {"#C(#40404B)3. Người chơi lọt vào #C(#1A954A)Top 128#C(#40404B) trong Vòng Loại có thể tham gia Chung Kết, và chọn ra quán quân cuối cùng."}
TAB_Describe[3047] = {"Xếp hạng Vòng Loại: %s"}
TAB_Describe[3048] = {"Duy trì hạng này trong Chung Kết sẽ được nhận thưởng"}
TAB_Describe[3049] = {"Giải Đỉnh Cao - Vòng Loại"}
TAB_Describe[3050] = {"#C(#40404B)1. Tuyển thủ tham gia Giải Đỉnh Cao (Vòng Loại) sẽ áp dụng quy tắc đối chiến theo cơ chế xếp hạng, #C(#1A954A)sau khi khiêu chiến thắng lợi sẽ trực tiếp thay thế xếp hạng của đối phương#C(#40404B)."}
TAB_Describe[3051] = {"#C(#40404B)2. Trước khi khiêu chiến Giải Đỉnh Cao (Vòng Loại) có thể xem đội hình đối phương, mỗi lần chiến đấu gồm 17 lượt. Nếu trận chiến vẫn chưa kết thúc khi đã hết lượt, thì phe thủ được tính thắng lợi."}
TAB_Describe[3052] = {"#C(#40404B)3. Người chơi đã tiến vào Giải Đỉnh Cao (Vòng Loại) có thể đồng thời tham gia Giải Thường Niên."}
TAB_Describe[3053] = {"#C(#40404B)4. Mở khiêu chiến vào #C(#1A954A)00:00-23:30#C(#40404B) mỗi ngày, không thể khiêu chiến vào nửa tiếng cuối ngày, hãy chú ý."}
TAB_Describe[3054] = {"Giải Đỉnh Cao-Chung Kết"}
TAB_Describe[3055] = {"#C(#40404B)1. Sáng sớm ngày cuối cùng của Giải Đỉnh Cao, lập danh sách giao đấu dựa trên Top 128 của Giải Đỉnh Cao (Vòng Loại), #C(#1A954A)20:00 tối#C(#40404B) tiến hành cạnh tranh Giải Đỉnh Cao (Chung Kết). Nếu không đủ #C(#1A954A)16 người#C(#40404B) đạt điều kiện tham gia giải thì Chung Kết sẽ không được mở."}
TAB_Describe[3056] = {"#C(#40404B)2. Trong thời gian thi đấu, tất cả người chơi mở Giải Bậc Chí Tôn đều có thể tiến hành dự đoán. Sau khi thi đấu kết thúc, dựa trên Xu Dự Đoán người chơi nhận được để đổi thành Huy Chương Vinh Dự."}
TAB_Describe[3057] = {"#C(#40404B)3. Giải Đỉnh Cao (Chung Kết) là giải đấu loại, người thắng được tăng cấp và giành hạng cao. Các tuyển thủ bị loại sẽ #C(#1A954A)được quyết định thứ tự xếp hạng dựa trên thứ hạng cao thấp trong Giải Đỉnh Cao (Vòng Loại)#C(#40404B)."}
TAB_Describe[3058] = {"#C(#40404B)4. Có thể nhận thưởng phong phú dựa vào xếp hạng trong Giải Đỉnh Cao (Chung Kết). SV có Top 3 còn được phát #C(#1A954A)Lì Xì Chúc Mừng#C(#40404B)."}
TAB_Describe[3059] = {"#C(#40404B)5. Trong Giải Đỉnh Cao (Chung Kết), nếu chưa phân thắng bại sau khi lượt đấu kết thúc, thì người chơi #C(#1A954A)xếp hạng cao trong Vòng Loại#C(#40404B) được tính chiến thắng."}
TAB_Describe[3060] = {"#C(#40404B)1. Chiến thắng giành được trong Giải Đỉnh Cao (Vòng Loại) và Giải Đỉnh Cao (Chung Kết) đều được tính vào lượt chiến thắng trong Giải Đỉnh Cao."}
TAB_Describe[3061] = {"#C(#40404B)2. Xếp hạng của Vòng Loại Giải Đỉnh Cao được tính theo xếp hạng kỷ lục của người chơi trong Vòng Loại."}
TAB_Describe[3062] = {"#C(#40404B)3. Sau khi hoàn thành nhiệm vụ hãy nhanh chóng nhận thưởng. Mùa giải mới sẽ tiến hành cài lại tiến độ nhiệm vụ, lúc này thưởng chưa nhận sẽ bị xóa."}
