TAB_Describe[3189] = {"#C(#40404B)1. Mỗi tấm Thẻ Tarot đều có thể cung cấp cho anh hùng 2 dòng #C(#1A954A)tỉ lệ thuộc tính#C(#40404B), còn có thể cung cấp 1 dòng #C(#1A954A)hiệu quả Thẻ Tarot#C(#40404B) đặc biệt, tăng mạnh lực chiến của anh hùng này ở một phương diện nào đó."}
TAB_Describe[3190] = {"#C(#40404B)2. Thẻ Tarot là #C(#1A954A)trang bị có tính duy nhất#C(#40404B), nhận nhiều lần sẽ bị phân tách thành Xu Quyền Trượng. Hãy xem xét cẩn thận dựa trên đội hình và trang bị cho anh hùng cần nó nhất"}
TAB_Describe[3191] = {"#C(#40404B)3. Thẻ Tarot có thể tăng cấp, tăng cấp có thể tăng #C(#1A954A)thuộc tính Thẻ Tarot#C(#40404B)."}
TAB_Describe[3192] = {"#C(#40404B)4. Sau khi tăng đến cấp nhất định còn có thể tăng bậc, tăng bậc không những có thể tăng mạnh #C(#1A954A)thuộc tính Thẻ Tarot#C(#40404B), mà còn có thể cường hóa #C(#1A954A)hiệu quả Thẻ Tarot#C(#40404B)."}
TAB_Describe[3193] = {"#C(#40404B)5. Có thể cài lại Thẻ Tarot. #C(#1A954A)100%#C(#40404B) hoàn trả #C(#1A954A)toàn bộ#C(#40404B) vật liệu dùng khi tăng cấp và tăng bậc."}
TAB_Describe[3194] = {"Đổi ngôn ngữ"}
TAB_Describe[3195] = {"Xác nhận đổi"}
TAB_Describe[3196] = {"Anh hùng bị thương đã nhận trị liệu bằng thuốc"}
