TAB_Describe[3198] = {"Thành công chiêu mộ Anh Hùng Chi Viện qua điện thoại"}
TAB_Describe[3199] = {"Thành công nhấn Nút Thần Bí"}
TAB_Describe[3200] = {"Triệu hồi viện quân Ninja, bắn phi tiêu vào mọi kẻ địch tạo sát thương"}
