TAB_Describe[3203] = {"Song Sinh Ám Ảnh hồi sinh tại chỗ, diệt bản thể Ám Ảnh mới bài trừ được lời nguyền bất tử"}
TAB_Describe[3204] = {"Cấp VIP%s mới có thể sửa tên Guild và tuyên ngôn Guild"}
TAB_Describe[3205] = {"Đạt cấp VIP%s mới có thể chat riêng"}
TAB_Describe[3206] = {"Phát vào 0h mỗi ngày"}
TAB_Describe[3207] = {"Mở khóa khi vượt ải chính %s"}
TAB_Describe[3208] = {"#C(#40404B)1. Ải Viễn Chinh có nhiều yếu tố bản đồ, khám phá bản đồ có thể nhận lợi ích tương ứng."}
TAB_Describe[3209] = {"#C(#40404B)2. Ải Viễn Chinh có thể có #C(#1A954A)nhiều tuyến đường#C(#40404B), tìm thấy tuyến đường tốt nhất có thể nhận được Rương Thẻ Tarot cuối cùng dễ dàng hơn."}
TAB_Describe[3210] = {"#C(#40404B)3. Viễn chinh có thể rút lui mở lại hoặc đổi ải viễn chinh bất cứ lúc nào, sau khi rút lui mở lại hoặc đổi ải, sẽ cài lại #C(#1A954A)toàn bộ yếu tố bản đồ trừ rương#C(#40404B) trong ải này. Rút lui mở lại xong được vào lại ải bất cứ lúc nào, không cần tốn gì."}
TAB_Describe[3211] = {"#C(#40404B)4. Sau khi đánh bại địch được nhận chiến lợi phẩm. Chiến lợi phẩm chỉ sinh hiệu lực trong #C(#1A954A)lần viễn chinh này#C(#40404B), rút lui mở lại hoặc đổi ải viễn chinh khiêu chiến thì chiến lợi phẩm đã nhận tự động biến mất."}
TAB_Describe[3212] = {"#C(#40404B)5. Rương trong ải viễn chinh tối đa chỉ được nhận #C(#1A954A)1 lần #C(#40404B). Sau khi rút lui mở lại khiêu chiến lần nữa, rương đã nhận sẽ không xuất hiện lại."}
TAB_Describe[3213] = {"#C(#40404B)6. Quân địch đã chiến thắng, sau khi rút lui mở lại, có thể #C(#1A954A)bỏ qua chiến đấu#C(#40404B)."}
