TAB_Describe[3322] = {"Kỹ năng hoàn thiện đã cài lại"}
TAB_Describe[3323] = {"Rương Đế Vương 11-11"}
TAB_Describe[3324] = {"1. Anh hùng đạt 13 sao mở kế hoạch hoàn thiện nhân loại\n\n2. Thông qua kế hoạch này anh hùng sẽ nâng cao tăng trưởng 4 thuộc tính lớn là HP, tấn công, phòng thủ, tốc độ, còn nhận được kỹ năng hoàn thiện mới\n\n3. Khi tăng trưởng được nâng cao, thuộc tính cơ bản tương ứng của anh hùng sẽ nâng cao, thuộc tính cơ bản không tương đương với thuộc tính cuối cùng, nó còn có thể tăng thêm hiệu quả Buff như tăng sao, Ấn Ký\n\n4. Khi 13 sao có thể tiến hành hoàn thiện ở Cây Sự Sống, mỗi lần tỉ lệ đồng bộ hoàn thiện đạt 100%, sau khi cấp hoàn thiện tăng, anh hùng nhận thêm 3 kỹ năng hoàn thiện, người chơi có thể chọn 1 kỹ năng để sử dụng\n\n5. Khi anh hùng tiến vào cảnh giới Linh Nhật, có thể tiến hành hoàn hiện cho Cây Tà Ác, mỗi lần tỉ lệ đồng bộ hoàn thiện đạt 100%, sau khi cấp hoàn thiện tăng, số lần anh hùng có thể dùng kỹ năng hoàn thiện không đổi, nhưng sẽ tăng thêm 1 kỹ năng hoàn thiện cho người chơi chọn dùng\n\n6. Tất cả tiêu hao dưỡng của kế hoạch hoàn thiện nhân loại sẽ được hoàn trả toàn bộ khi anh hùng được chuyển đổi, hủy hiệp ước, điều trả,..."}
