TAB_Describe[3418] = {"Chỉ được khảm 1 thẻ cùng tên"}
TAB_Describe[3419] = {"Chưa đạt điều kiện mở"}
TAB_Describe[3420] = {"#C(#40404B)1.#C(#1A954A)Thẻ chưa giám định#C(#40404B) có thể đặt ở Ô Giám Định để giám định. Giám định cần 1 thời gian nhất định. Thời gian tùy theo #C(#1A954A)phẩm chất của thẻ#C(#40404B) chưa giám định."}
TAB_Describe[3421] = {"#C(#40404B)2. Ban đầu mở #C(#1A954A)1#C(#40404B) Ô Giám Định. Người chơi đạt đến #C(#1A954A)số bậc nhất định của Duel Disk#C(#40404B), có thể tốn lượng Kim Cương nhất định, mở khóa vĩnh viễn #C(#1A954A)Ô Giám Định thứ 2#C(#40404B)."}
TAB_Describe[3422] = {"#C(#40404B)3. Ô Giám Định đặc quyền được mở khóa sau khi #C(#1A954A)kích hoạt đặc quyền#C(#40404B). Sau khi đặc quyền hết hạn, Ô Giám Định đặc quyền mất hiệu lực. Khi mất hiệu lực, nếu Ô Giám Định có Thẻ đang giám định, thì sẽ mất hiệu lực sau khi hoàn thành giám định. "}
TAB_Describe[3423] = {"#C(#40404B)1. Duel Disk tham gia chiến đấu với tư cách là một đơn vị chiến đấu độc lập, có thuộc tính và lực chiến riêng."}
TAB_Describe[3424] = {"#C(#40404B)2. Sau khi Duel Disk khảm thẻ mới có thể tham gia chiến đấu. "}
TAB_Describe[3425] = {"#C(#40404B)3. Mỗi thẻ có kỹ năng đặc biệt riêng."}
TAB_Describe[3426] = {"#C(#40404B)4. Thứ tự khảm thẻ quyết định kỹ năng mà thẻ dành cho sẽ được thi triển trong vòng nào – Xoay vòng theo lượt 1, 2, 3, 4 của thứ tự khảm."}
TAB_Describe[3427] = {"#C(#40404B)5. Thẻ nhận được thông qua Giám Định."}
TAB_Describe[3428] = {"#C(#40404B)6. Thẻ chưa giám định có thể nhận được bằng cách #C(#40404B)dùng Vàng mua, tính năng xuất ra, sự kiện xuất ra#C(#40404B)."}
TAB_Describe[3429] = {"#C(#40404B)7. Thẻ có thể phân tách, phân tách thẻ có thể nhận nguyên liệu tăng cấp Duel Disk."}
TAB_Describe[3430] = {"#C(#40404B)8. Thuộc tính Duel Disk chia thành #C(#1A954A)thuộc tính bản thân#C(#40404B) và #C(#1A954A)thuộc tính kế thừa#C(#40404B). Thuộc tính cơ bản quyết định bởi cấp độ và bậc của Duel Disk, thuộc tính kế thừa do #C(#1A954A)tổng thuộc tính#C(#40404B) của đội Duel Disk ở hiện tại, sau một tỷ lệ quy đổi nhất định, nó được nhân với #C(#1A954A)hệ số kế thừa thuộc tính#C(#40404B) hiện tại của Duel Disk để tính."}
TAB_Describe[3431] = {"#C(#40404B)9. Duel Disk có thể tăng cấp hoặc tăng bậc. Tăng cấp hoặc tăng bậc có thể tăng #C(#1A954A)thuộc tính Duel Disk#C(#40404B), tăng bậc còn có thể mở khóa #C(#1A954A)Ô Thẻ#C(#40404B), hoặc tăng #C(#1A954A)hệ số kế thừa thuộc tính#C(#40404B) của Duel Disk."}
TAB_Describe[3432] = {"#C(#40404B)10. Sau khi người chơi đạt cấp 150, mở Dưỡng tiến hóa Kính Toái: Thẻ Truyền Thuyết tăng đến 5 sao có thể #C(#1A954A)tiến hóa Kính Toái#C(#40404B), tiến hóa Kính Toái xong được tăng #C(#1A954A)hiệu quả kỹ năng Thẻ#C(#40404B); thẻ sau khi tiến hóa tách sẽ mất thẻ tiến hóa nhưng hoàn toàn giữ lại vật liệu tiến hóa. "}
