TAB_Describe[3453] = {"Cảm ơn bạn đã chọn game! Chúng tôi rất coi trọng việc bảo vệ thông tin cá nhân và quyền riêng tư của bạn. Để bảo vệ quyền cá nhân của bạn tốt hơn, vui lòng đọc kỹ “Thỏa thuận người dùng” và “Chính sách bảo mật” trước khi bạn sử dụng dịch vụ của chúng tôi để hiểu rõ việc chúng tôi thu thập, sử dụng và lưu trữ thông tin cá nhân của người dùng cũng như các quyền liên quan của bạn. Vui lòng đọc kỹ và hiểu đầy đủ các nội dung liên quan, nếu bạn đã đọc và đồng ý với tất cả các điều khoản, vui lòng nhấp vào “Đồng ý” để bắt đầu dịch vụ của chúng tôi."}
TAB_Describe[3454] = {"#C(#2B2B34)Người chơi đạt Lv65, cấp anh hùng đạt 10 sao sẽ mở vũ khí chuyên thuộc;\n\nĐa số anh hùng chính đều có vũ khí chuyên thuộc, vũ khí chuyên thuộc có thể cường hóa đặc sắc và năng lực anh hùng;\n\nThuộc tính vũ khí chuyên thuộc cung cấp cho anh hùng là #C(#BF8619)thuộc tính cơ bản #C(#2B2B34), có thể mở rộng tỉ lệ được tham gia những dưỡng khác;\n\nCó thể cài lại dưỡng của vũ khí chuyên thuộc, 100% hoàn trả vật liệu dưỡng;\n\nLúc anh hùng bị thôn tính, đổi Khế Ước, chuyển đổi cao cấp, cũng sẽ 100% hoàn trả vật liệu dưỡng của vũ khí chuyên thuộc."}
