TAB_Describe[3588] = {"#C(#40404B)3. Vũ khí chuyên thuộc tăng cho anh hùng #C(#1A954A)thuộc tính cơ bản#C(#40404B), thuộc tính này có thể #C(#1A954A)mở rộng tỉ lệ #C(#40404B) tham gia dưỡng thành khác. "}
TAB_Describe[3589] = {"#C(#40404B)4. Có thể cài lại vũ khí chuyên thuộc, #C(#1A954A)100% #C(#40404B)hoàn trả #C(#1A954A)toàn bộ #C(#40404B)vật liệu dùng để kích hoạt, tăng cấp và tăng bậc. "}
TAB_Describe[3590] = {"#C(#40404B)5. Lúc anh hùng bị thôn tính, đổi Khế Ước, chuyển đổi cao cấp cũng sẽ #C(#1A954A)100% #C(#40404B)hoàn trả toàn bộ vật liệu dưỡng của vũ khí chuyên thuộc. "}
