TAB_Describe[3603] = {"#C(#40404B)1. Người chơi đạt #C(#1A954A)Lv120#C(#40404B), mở lối chơi Quyết Đấu Vương Quốc, thời gian khiêu chiến từ #C(#1A954A)5:00 thứ 2#C(#40404B)-#C(#1A954A)11:00 chủ nhật #C(#40404B). "}
TAB_Describe[3604] = {"#C(#40404B)2. Quyết Đấu Vương Quốc được chia thành #C(#1A954A)11 tầng#C(#40404B), thủ vệ phe địch tương ứng là anh hùng #C(#1A954A)5-13 sao, cảnh giới Linh Nguyệt, Linh Nhật#C(#40404B), người chơi có thể cho anh hùng ra trận để khiêu chiến, chỉ tạo ra thuộc tính tương ứng dựa trên #C(#1A954A)cấp sao của anh hùng#C(#40404B), dưỡng thành khác đều không có hiệu lực trong khiêu chiến lối chơi này. "}
TAB_Describe[3605] = {"#C(#40404B)3. Khi số tầng tăng lên, thủ vệ của phe địch sẽ từ một đội hình biến thành #C(#1A954A)nhiều đội hình#C(#40404B), ở mỗi tầng người chơi có thể chọn ra 1 anh hùng trợ chiến hệ thống làm trợ thủ."}
TAB_Describe[3606] = {"#C(#40404B)4. Khiêu chiến thủ vệ phe địch thành công, phe ta sẽ được #C(#1A954A)Thẻ Quyết Đấu trợ chiến #C(#40404B) (Chỉ dùng trong lối chơi này), đồng thời thuộc tính của những thủ vệ còn lại của phe địch sẽ nâng cao. "}
TAB_Describe[3607] = {"#C(#40404B)5. Căn cứ biểu hiện khiêu chiến ải của người chơi (#C(#1A954A)số lượng anh hùng tử vong, số lượt đã dùng #C(#40404B)), người chơi sẽ nhận được điểm vượt ải; vào mỗi #C(#1A954A)23:00 chủ nhật #C(#40404B)lúc kết thúc lối chơi hệ thống sẽ phát thưởng dựa trên xếp hạng liên SV."}
TAB_Describe[3608] = {"#C(#40404B)6. Nếu người chơi không hài lòng với kết quả khiêu chiến ở tầng nào đó, có thể cài lại mọi lúc, cài lại không ảnh hưởng điểm vượt ải cao nhất tuần này."}
TAB_Describe[3609] = {"Thủ vệ ải này đã bị đánh bại, cài lại tầng này mới được khiêu chiến lại"}
