TAB_Describe[3619] = {"#C(#40404B)1. Người chơi đạt #C(#1A954A)Lv70#C(#40404B), mở lối chơi Mê Cung Bàn Cờ, thời gian khiêu chiến từ #C(#1A954A)5:00 thứ 2#C(#40404B)#C(#1A954A)23:00 chủ nhật #C(#40404B). "}
TAB_Describe[3620] = {"#C(#40404B)2. Người chơi tung xúc xắc trong Mê Cung Bàn Cờ, dọc đường sẽ nhặt quân cờ #C(#1A954A)tăng thuộc tính cho anh hùng ra trận của phe ta #C(#40404B)(có hiệu lực ở tầng này), nhận được #C(#1A954A)hiệu quả tăng cường của vũ khí chuyên thuộc #C(#40404B)(có hiệu lực ở tuần này), thưởng đạo cụ như #C(#1A954A)rương lớn #C(#40404B)... "}
TAB_Describe[3621] = {"#C(#40404B)3. Xúc xắc có hai loại màu trắng và đỏ: Xúc xắc trắng mỗi ngày vào #C(#1A954A)0 giờ #C(#40404B), #C(#1A954A)12 giờ #C(#40404B)tự động làm mới #C(#1A954A)5 cái#C(#40404B), giới hạn lưu trữ #C(#1A954A)20 cái#C(#40404B); Xúc xắc đỏ cần phải mua và dùng làm đạo cụ lâu dài."}
TAB_Describe[3622] = {"#C(#40404B)4. Người chơi khiêu chiến thủ vệ tầng này thành công có thể #C(#1A954A)vào tầng tiếp theo #C(#40404B), nếu thất bại sẽ #C(#1A954A)trở về vị trí ban đầu của tầng này #C(#40404B)để khiêu chiến lại, ngoại trừ đạo cụ tăng cường vũ khí chuyên thuộc ra, các nguyên tố khác đều sẽ cài lại."}
TAB_Describe[3623] = {"#C(#40404B)5. Vào #C(#1A954A)23:00 chủ nhật mỗi tuần #C(#40404B)lúc kết thúc lối chơi, hệ thống sẽ phát thư thưởng dựa trên xếp hạng số tầng tuần này của người chơi."}
TAB_Describe[3624] = {"#C(#40404B)6. Vào #C(#1A954A)5:00 thứ 2 mỗi tuần #C(#40404B)sau khi mở lối chơi, sẽ trả lại số tầng nhất định dựa trên tình hình người chơi vượt ải tuần này, vượt ải càng nhiều sẽ trả lại càng nhiều, sau tầng 20 sẽ mở tính năng #C(#1A954A)Tốc hành #C(#40404B). "}
