TAB_Describe[3689] = {"#C(#40404B)2. Tặng quà đồng thời có thể tăng #C(#1A954A)điểm hấp dẫn#C(#40404B), cấp điểm hấp dẫn có thể buff cho toàn thể anh hùng, điểm hấp dẫn cứ tăng 10 cấp còn nhận thêm #C(#1A954A)buff cấp #C(#40404B). "}
TAB_Describe[3690] = {"#C(#40404B)3. Quà cao cấp có thể #C(#1A954A)tăng thuộc tính anh hùng#C(#40404B), nhưng số lần tặng quà cao cấp #C(#1A954A)có giới hạn #C(#40404B). Số lượng được tặng sẽ quyết định bởi cấp sao cao nhất trong lịch sử của anh hùng, tăng cấp sao anh hùng có thể mở khóa giới hạn số lượng quà cao cấp tặng hoặc được tặng. "}
