TAB_Describe[3745] = {"#C(#40404B)1. Thủ lĩnh Guild mở khiêu chiến vào #C(#1A954A)18:00 #C(#40404B)mỗi ngày, #C(#1A954A)20:00 #C(#40404B)kết thúc khiêu chiến, sau khi kết thúc #C(#1A954A)lập tức mở đấu giá."}
TAB_Describe[3746] = {"#C(#40404B)2. Sau khi mở sự kiện, tất cả người chơi gia nhập Guild trong nhóm liên SV thuộc server hiện tại sẽ khiêu chiến chung một thủ lĩnh."}
TAB_Describe[3747] = {"#C(#40404B)3. Người chơi tham gia SK với tư cách thành viên Guild, cấp Guild cần đạt #C(#1A954A)Lv3 #C(#40404B), mỗi lần sự kiện có #C(#1A954A)5 lần #C(#40404B) cơ hội khiêu chiến."}
TAB_Describe[3748] = {"#C(#40404B)4. Thưởng sát thương cá nhân: Tổng lượng sát thương tích lũy đạt yêu cầu có thể nhận thưởng của mốc tương ứng, mỗi lần sự kiện chỉ được nhận 1 lần thưởng ở mỗi mốc. "}
TAB_Describe[3749] = {"#C(#40404B)5. Sát thương Guild là tổng sát thương tích lũy của tất cả thành viên Guild, lúc kết thúc sự kiện sẽ phát vật phẩm đấu giá dựa trên hạng sát thương Guild, tiến hành đấu giá trong Guild này."}
TAB_Describe[3750] = {"#C(#40404B)6. Xếp hạng liên SV sát thương Guild: Xếp hạng tổng lượng sát thương Guild trong nhóm liên SV hiện tại, xếp hạng càng cao thì chất lượng vật phẩm đấu giá Guild nhận được càng cao."}
TAB_Describe[3751] = {"#C(#40404B)7. Xếp hạng sát thương Guild SV này: Xếp hạng tổng lượng sát thương Guild trong SV hiện tại, xếp hạng càng cao và càng nhiều thành viên trong Guild tham gia sự kiện thì số lượng vật phẩm bán đấu giá càng nhiều."}
TAB_Describe[3752] = {"#C(#40404B)1. Đấu giá Guild mở vào #C(#1A954A)20:00 #C(#40404B)mỗi ngày, Đấu giá Thế Giới mở vào #C(#1A954A)20:15 #C(#40404B)mỗi ngày."}
TAB_Describe[3753] = {"#C(#40404B)2. Vật phẩm trong Đấu giá Guild là thưởng sự kiện cho Guild này hôm nay tham gia Thủ lĩnh Guild, tất cả thành viên Guild này có thể tham gia đấu giá."}
TAB_Describe[3754] = {"#C(#40404B)3. Vật phẩm đấu giá thành công sẽ gửi qua thư cho người chơi, bị vượt lên khiến đấu giá thất bại sẽ hoàn trả tất cả Kim Cương người chơi đã dùng để đấu giá, mua ngay có thể trực tiếp nhận được vật phẩm. "}
TAB_Describe[3755] = {"#C(#40404B)4. Lúc kết thúc đấu giá Guild, sau khi hệ thống thu một mức thuế Kim Cương nhất định, thành viên Guild tham gia khiêu chiến Thủ lĩnh Guild có thể nhận Kim Cương lợi nhuận của lần đấu giá này. (Khi không đủ 8 người sẽ chia hoa hồng theo 8 người)"}
TAB_Describe[3756] = {"#C(#40404B)5. Lúc kết thúc đấu giá Guild, một số vật phẩm đấu giá trượt sẽ vào hàng đấu giá thế giới để toàn bộ người chơi server này đấu giá."}
TAB_Describe[3757] = {"#C(#40404B)6. Sau khi kết thúc đấu giá Thế Giới, Guild này bán vật phẩm trong đấu giá thế giới xong nhận Kim Cương sẽ chia lãi lần nữa."}
