TAB_Describe[4095] = {"#C(#40404B)2. Lúc đầu độ khó là D, sau khi người chơi #C(#1E90FF)vượt ải 3 tầng#C(#40404B), mở ải tiếp theo độ khó sẽ tăng lên 1 mốc, cao nhất có thể đạt ACE"}
