TAB_Describe[4133] = {"#C(#40404B)1. Anh hùng đạt 13 sao và Tháp Cộng Hưởng cấp 360 mở tính năng Linh Hồn, cấp Tháp Cộng Hưởng đạt #C(#008000)360#C(#40404B) có thể mở khóa Nguyệt Liên vào cảnh giới #C(#008000)Linh Nguyệt#C(#40404B), cấp Tháp Cộng Hưởng đạt #C(#008000)390#C(#40404B) có thể mở khóa Nhật Liên vào cảnh giới #C(#008000)Linh Nhật#C(#40404B)."}
TAB_Describe[4134] = {"#C(#40404B)2. Thông qua Linh Hồn mở khóa Anh Hùng có thể tăng tăng trưởng HP và công bản thân, vào cảnh giới Linh Nguyệt còn được tư thế {Vạn Giải} và {Quy Nhận/Thể Hoàn Hảo}, có thể chọn một để dùng, vào cảnh giới Linh Nhật sẽ tiến thêm 1 bước cường hóa tư thế {Vạn Giải} và {Quy Nhận/Thể Hoàn Hảo}. (Tư thế {Thể Hoàn Hảo} chỉ Yhwach Quincy mới sở hữu)"}
TAB_Describe[4135] = {"#C(#40404B)3. Anh hùng mở giải phóng Linh Hồn có thể tiến hành giải ước cao cấp và chuyển đổi khế ước, tiêu tốn vật liệu cần và hoàn trả khi vật liệu trả về sẽ dựa vào tiến độ mở khóa giải phóng Linh Hồn hiện tại của bản thân anh hùng để tính toán."}
