TAB_Describe[4179] = {"Quy tắc mở"}
TAB_Describe[4180] = {"#C(#40404B)1. Yuusuke kế thừa di chí Raizen, đề nghị chọn người thống trị Ma Giới thông qua tỷ võ, thế là quyết định một trận tỷ võ toàn Ma Giới. Ma Thuật Chiến là lối chơi PVP nhiều đội hình, có thể ra trận 3 đội để thi đấu, có thể ra trận #C(#1E90FF)3 đội#C(#40404B) để thi đấu."}
TAB_Describe[4181] = {"#C(#40404B)2. Server có số ngày mở ≥ #C(#1E90FF)50 ngày#C(#40404B) vào mỗi 0h thứ 2 sẽ tiến hành bắt cặp rồi mở báo danh, tổng số người báo danh ≥ #C(#1E90FF)4#C(#40404B) chính thức mở Ma Thuật Chiến."}
TAB_Describe[4182] = {"#C(#40404B)3. Sau khi mở Ma Thuật Chiến, mỗi kỳ chính thức mở từ #C(#1E90FF)0h thứ 3 tuần này#C(#40404B), cho đến #C(#1E90FF)23h thứ 7 tuần sau#C(#40404B) mới kết thúc và phát thưởng, trong thời gian này có thể tiến hành khiêu chiến vào #C(#1E90FF)mỗi thứ 3, 5, 7#C(#40404B)."}
TAB_Describe[4183] = {"#C(#40404B)4. Sau khi báo danh thành công lần đầu, thi đấu về sau sẽ tự động báo danh, nếu người chơi trong một thời gian dài chưa online sẽ bị đá ra, cần báo danh lại."}
TAB_Describe[4184] = {"Quy tắc báo danh"}
TAB_Describe[4185] = {"#C(#40404B)1. Lần đầu tiến hành báo danh thi đấu, phải báo danh thủ công, cần thiết lập đội hình phòng thủ mới được báo danh."}
TAB_Describe[4186] = {"#C(#40404B)2. Người chơi đã thi đấu sẽ tự động tiến hành báo danh khi Ma Thuật Chiến kỳ sau mở báo danh."}
TAB_Describe[4187] = {"Quy tắc khiêu chiến"}
TAB_Describe[4188] = {"#C(#40404B)1. Người chơi thi đấu lần đầu số điểm là 1000, không phải thi đấu lần đầu sẽ dựa vào số điểm cuối cùng kỳ trước để tiến hành cài lại, khi khiêu chiến căn cứ vào điểm bản thân để bắt cặp đối thủ, mỗi lần bắt cặp 3 đối thủ hơn nữa còn có thể làm mới."}
TAB_Describe[4189] = {"#C(#40404B)2. Người chơi dùng 3 đội tiến hành thi đấu, số lượng anh hùng có thể ra trận mỗi đội được quyết định bởi #C(#1E90FF)cấp bình quân thế giới#C(#40404B) ở phân nhóm Liên SV, từ #C(#1E90FF)3~6 người#C(#40404B); trong vài trường hợp cực đoan, nếu số người khiêu chiến lần này ít hơn số người khiêu chiến lần trước thì sẽ cưỡng chế thay đổi đội người chơi, điểm này cần mọi người chú ý."}
TAB_Describe[4190] = {"#C(#40404B)3. Sau khi đối thủ chọn tiến hành khiêu chiến, đội hai bên lần lượt tiến hành chiến đấu đội thứ 1, 2, 3, dùng cơ chế #C(#1E90FF)3 thắng 2#C(#40404B) quyết định thắng bại."}
TAB_Describe[4191] = {"#C(#40404B)4. Nếu đội nào đó của hai bên đối chiến trống hoặc chiến đấu quá giờ thì bên phòng thủ thắng."}
TAB_Describe[4192] = {"#C(#40404B)5. Sau khi phân thắng bại, dựa vào điểm hiện tại của hai bên và kết quả chiến đấu để tăng hoặc giảm điểm tương ứng."}
TAB_Describe[4193] = {"Quy tắc thưởng"}
TAB_Describe[4194] = {"#C(#40404B)1. Sau mỗi lần tiến hành khiêu chiến có thể nhận được phần thưởng nhất định, đạt yêu cầu thắng tích lũy tương ứng được nhận thưởng thêm."}
TAB_Describe[4195] = {"#C(#40404B)2. Khi kết thúc mỗi kỳ dựa vào số điểm hiện tại để tiến hành xếp hạng, phát thưởng xếp hạng qua thư, cụ thể có thể xem trong giao diện thưởng mùa giải."}
TAB_Describe[4196] = {"#C(#40404B)3. Điểm Ma Thuật có thể dùng để đổi vật phẩm hiếm trong Tiệm Ma Thuật."}
TAB_Describe[4197] = {"#C(#40404B)1. Thông qua kế thừa trang bị có thể cộng hưởng bộ phận dưỡng của một anh hùng nào đó cho anh hùng khác, dưỡng kế thừa được bao gồm: Trang bị, Phụ Linh, Ấn Ký, Thiên Phú, Bảo Khí. Anh hùng (bao gồm kế thừa và được kế thừa) trong chuỗi kế thừa ở lối chơi đội hình đơn không thể đồng thời ra trận, lối chơi nhiều đội hình không giới hạn "}
TAB_Describe[4198] = {"#C(#40404B)2. Anh hùng đạt #C(#1E90FF)13 sao trở lên#C(#40404B) có thể mang trang bị kế thừa cho anh hùng khác, sau khi mở khóa vị trí kế thừa sẽ đưa trang bị kế thừa cho nhiều vị trí anh hùng, anh hùng đạt đến #C(#1E90FF)11 sao trở lên#C(#40404B) mới được kế thừa trang bị của anh hùng khác."}
TAB_Describe[4199] = {"#C(#40404B)3. Anh hùng dùng trang bị kế thừa phải đạt #C(#1E90FF)yêu cầu phẩm chất#C(#40404B) nhất định mới được anh hùng khác kế thừa thành công, yêu cầu phẩm chất tối thiểu: Trang bị đỏ 3 sao, bảo khí hoàn mỹ 3 sao, Ấn Ký V, Thiên Phú cao cấp"}
TAB_Describe[4200] = {"#C(#40404B)4. Khi tiến hành kế thừa trang bị, nếu nghề anh hùng tham gia kế thừa không giống nhau, một số kỹ năng và thuộc tính Bảo Khí khi kế thừa sẽ phân phối nghề #C(#1E90FF)tự động chuyển đổi#C(#40404B), sau khi chuyển đổi nếu đã có kỹ năng/thuộc tính giống nhau sẽ không cộng dồn, kết quả chuyển đổi cụ thể xem trong chi tiết kế thừa."}
TAB_Describe[4201] = {"#C(#40404B)5. Khi anh hùng đang kế thừa trang bị của anh hùng khác, với Ấn Ký, Thiên Phú, Bảo Khí đều có thể #C(#1E90FF)cài đặt riêng#C(#40404B) kế thừa anh hùng khác hay không, nếu chọn đóng thì dùng dưỡng tương ứng của bản thân."}
