TAB_Describe[4251] = {"Đang kế thừa trang bị"}
TAB_Describe[4252] = {"#C(#40404B)1. Cấp người chơi đạt #C(#1E90FF)150#C(#40404B) mở tính năng Servant, khi anh hùng đạt đến #C(#1E90FF)cảnh giới Linh Nguyệt#C(#40404B) có thể tiến hành dưỡng Servant."}
TAB_Describe[4253] = {"#C(#40404B)2. Kích hoạt Servant được nhận Buff thuộc tính thường quy, hơn nữa sẽ nhận Buff #C(#1E90FF)thuộc tính PVP#C(#40404B), Buff sinh hiệu lực cho tất cả anh hùng cùng tên."}
TAB_Describe[4254] = {"#C(#40404B)3. Servant có thể tiến hành #C(#1E90FF)tăng thứ hạng#C(#40404B), sau khi tăng thứ hạng được nhận thêm Buff thuộc tính, tối đa có thể nhận thêm #C(#1E90FF)5#C(#40404B) Buff thuộc tính."}
TAB_Describe[4255] = {"#C(#40404B)4. Khi nhận thêm Buff thuộc tính loại thuộc tính nhận ngẫu nhiên, theo thứ tự mở khóa, loại thuộc tính đến ngẫu nhiên của mỗi dòng thuộc tính có chỗ khác nhau."}
TAB_Describe[4256] = {"#C(#40404B)6. Buff thuộc tính thêm có thể thông qua Xây dựng khế ước #C(#1E90FF)làm lại phẩm chất Buff và loại thuộc tính ngẫu nhiên#C(#40404B), tốn thêm vật phẩm có thể tiến hành khóa, khi xây dựng lại loại thuộc tính bị khóa và trị số sẽ không ngẫu nhiên có lại. Sau khi làm lại thuộc tính ngẫu nhiên được chọn lưu hay không, lưu xong thuộc tính mới sẽ chồng lên thuộc tính ban đầu."}
TAB_Describe[4257] = {"#C(#40404B)7. Servant có thể tiến hành thu hồi thứ hạng, thu hồi xong tất cả Buff bị xóa sạch, thứ hạng Servant ở trạng thái chưa kích hoạt, đồng thời chỉ hoàn trả kích hoạt và tiêu hao tăng, #C(#1E90FF)không hoàn trả tiêu hao xây dựng khế ước#C(#40404B)。"}
