TAB_Describe[4334] = {"#C(#40404B)1. Sau khi người chơi vượt ải #C(#1E90FF)Viễn Chinh Bụi Sao#C(#40404B) mở khiêu chiến Thảo Phạt × Vua Kiến."}
TAB_Describe[4335] = {"#C(#40404B)2. Thảo Phạt × Vua Kiến là ải khiêu chiến đa đội hình 3V3, người chơi cần đồng thời ra trận 3 đội mà #C(#1E90FF)3 đội phải toàn thắng#C(#40404B) mới được vượt ải."}
TAB_Describe[4336] = {"#C(#40404B)3. 3 đội địch sẽ nhận Buff Vua Kiến 3 Hộ Vệ, ải độ khó càng cao Buff càng cao."}
TAB_Describe[4337] = {"#C(#40404B)4. Vượt ải có thể nhận thưởng AVA liên quan Vua Kiến."}
