TAB_Describe[4365] = {"Suton oshan"}
TAB_Describe[4366] = {"#C(#40404B)1. Cấp người chơi đạt #C(#1E90FF)160#C(#40404B) mở Suton Oshan, có thể nhận thế thân qua khiêu chiến hoặc vật liệu dưỡng của nó. "}
TAB_Describe[4367] = {"#C(#40404B)2. Ngày #C(#1E90FF)1#C(#40404B) mỗi tháng dựa vào #C(#1E90FF)lực chiến cao nhất lịch sử#C(#40404B) của người chơi quyết định cấp độ khó, cấp độ khó càng cao độ khó quái ải càng cao, đồng thời thưởng cũng sẽ tăng theo độ khó."}
TAB_Describe[4368] = {"#C(#40404B)3. Ở mỗi tầng có ải thường với 3 tuyến đường và 1 ải BOSS, cần#C(#1E90FF)vượt ải tuyến đường giữa#C(#40404B) mới được mở khóa ải BOSS và hai tuyến đường bên trái phải, vượt ải BOSS có thể vào khiêu chiến tầng tiếp theo."}
TAB_Describe[4369] = {"#C(#40404B)4. Khiêu chiến ải thường cần thỏa mãn giới hạn đội mới được vào khiêu chiến, anh hùng phe Hỗn Độn không bị giới hạn phe để tiến hành ra trận nhưng số lượng không được quá 2, #C(#1E90FF)vượt ải lần đầu#C(#40404B) cần tốn số lần khiêu chiến; mỗi ngày nhận 5 lần khiêu chiến, chưa dùng có thể tích lũy nhưng tối đa tích lũy đến 15 lần. #C(#1E90FF)3 ngày cuối#C(#40404B) mỗi tháng sẽ không hạn chế số lần. "}
TAB_Describe[4370] = {"#C(#40404B)5. Khiêu chiến ải Boss không tốn số lần khiêu chiến, có thể chọn hoặc không chọn #C(#1E90FF)kỹ năng thêm #C(#40404B)để quyết định cấp sao của Boss, cấp sao càng cao thưởng thêm càng lớn, thưởng của mỗi cấp sao chỉ được nhận 1 lần, tích lũy cấp sao được mở khóa mua càng nhiều đạo cụ quý hiếm. Ngoài ra: Lúc khiêu chiến Boss,#C(#FF3519)JOJO có thể được chọn làm anh hùng hỗ trợ."}
TAB_Describe[4371] = {"#C(#40404B)8.8. Ngày 1 mỗi tháng sẽ tiến hành cài lại cấp độ khó và ải, tiến độ ải, cấp sao tích lũy, số liệu số lần khiêu chiến và xếp hạng đều sẽ cài lại, số sao tích lũy Chiến Lệnh Suton Oshan #C(#1E90FF)sẽ không#C(#40404B) bị cài lại. "}
