TAB_Describe[4450] = {"#C(#40404B)3. Tiến hóa Sứ Giả Thế Thân có thể kích hoạt thêm hiệu quả đánh thường của anh hùng, và nhận thuộc tính thêm, tăng cấp tiến hóa cũng đồng thời tăng giới hạn số lần tăng trưởng Sứ Giả Thế Thân, ban đầu có thể tối đa tăng trưởng 20 lần, khi tiến hóa đến cấp 5, tăng trưởng không giới hạn số lần, cụ thể xem bảng chi tiết"}
