TAB_Describe[4540] = {"Nhấp bỏ qua hoạt hình"}
TAB_Describe[4541] = {"#C(#40404B)1. Phong vân Ma giới lại nổi lên, rất nhiều người thắng Ma Thuật Chiến giành lại đỉnh cao, quyết chọn ra Vương Giả duy nhất. Người chơi Top 32 Ma Thuật Chiến kỳ gần nhất của Vương Giả Ma Thuật tiến hành thi đấu, tối đa có 4 nhóm Liên SV, tổng cộng 128 người, không đủ 128 người sẽ lấy 64 hoặc 32 người tham gia thi đấu. "}
TAB_Describe[4542] = {"#C(#40404B)2. 0:00 mỗi thứ 2, server có số ngày mở ≥ #C(#1E90FF)50 ngày#C(#40404B) và Ma Thuật Chiến kỳ trước chọn ra #C(#1E90FF)Top 32#C(#40404B) sẽ tiến hành bắt cặp, sau khi bắt cặp thành công chính thức mở Vương Giả Ma Thuật. "}
TAB_Describe[4543] = {"Quy tắc thi đấu"}
TAB_Describe[4544] = {"#C(#40404B)1. Vương Giả Ma Thuật Chiến chọn ngẫu nhiên hai nhóm, từng hai cặp đối quyết, thắng tăng cấp thua bị loại, cho đến khi chọn ra Vương Giả cuối cùng. "}
TAB_Describe[4545] = {"#C(#40404B)2. 128 người tham chiến kéo dài trong 7 ngày: bắt đầu nhóm nhỏ 16 người, mỗi nhóm nhỏ đánh 2 vòng chọn ra 2 người vào Top 32; Top 32 ngẫu nhiên phân thành 4 nhóm nhỏ, đánh tiếp 2 vòng chọn ra Top 8; nhóm Top 8 đánh 3 vòng chọn ra quán quân. "}
TAB_Describe[4546] = {"#C(#40404B)3. Khi 64 người tham gia thi đấu, thứ 2 bỏ trống, thứ 3 bắt đầu duy trì 6 ngày: ban đầu 8 nhóm nhỏ, mỗi nhóm nhỏ đánh 3 vòng chọn hạng 1 vào Top 8; một nhóm Top 8 đánh 3 vòng chọn ra quán quân. "}
TAB_Describe[4547] = {"#C(#40404B)4. Khi 32 người tham gia thi đấu, thứ 2, 3 bỏ trống, thứ 4 bắt đầu duy trì 5 ngày: Ban đầu 4 đội nhỏ, mỗi đội nhỏ đánh 2 vòng chọn 2 hạng đầu vào Top 8; một nhóm Top 8 đánh 3 vòng chọn ra quán quân. "}
TAB_Describe[4548] = {"Quy tắc thi đấu"}
TAB_Describe[4549] = {"#C(#40404B)1. Trong thời gian thi đấu từ 0:00 đến 12:00 mỗi ngày là giai đoạn chuẩn bị, tất cả người chơi tham gia thi đấu có thể thiết lập và điều chỉnh đội đấu, sau khi kết thúc giai đoạn chuẩn bị thì khóa đội, trong ngày không thể điều chỉnh đội lại. "}
TAB_Describe[4550] = {"#C(#40404B)2. Thời gian sự kiện 12:00 đến 20:00 mỗi ngày là giai đoạn Dự đoán, mỗi vòng thi đấu sẽ phát động dự đoán cho một trận chỉ định, tất cả người chơi đều có thể tham gia dự đoán, mỗi vòng dự đoán #C(#1E90FF)giới hạn đặt cược và tỉ lệ thắng khác nhau #C(#40404B), điểm dự đoán nhận được đổi thưởng trong tiệm. "}
TAB_Describe[4551] = {"#C(#40404B)3. Thời gian thi đấu mỗi ngày 20:00 đến 20:30 là giai đoạn Chiến đấu, hệ thống tự động tiến hành, tất cả người chơi dùng 3 đội để chiến đấu, đội hai bên theo thứ tự đội 1, 2, 3 tiến hành chiến đấu, dùng cơ chế #C(#1E90FF)3 trận thắng 2#C(#40404B) quyết định thắng bại. Kẻ bại bị loại, người thắng tăng cấp vào vòng sau. "}
TAB_Describe[4552] = {"#C(#40404B)4. Trong thời gian thi đấu trừ bỏ trống ra, mỗi ngày đều dùng quy tắc trên tiến hành thi đấu, ngày cuối chọn ra Vương Giả cuối cùng. "}
TAB_Describe[4553] = {"#C(#40404B)1. Sau khi tất cả thi đấu kết thúc, phát thưởng qua thư dựa vào xếp hạng, quán quân và á quân sẽ nhận tôn hiệu chuyên thuộc. "}
TAB_Describe[4554] = {"#C(#40404B)2. Tất cả người chơi đều có thể thông qua tham gia dự đoán nhận thưởng tích điểm, đổi thưởng vật phẩm hậu hĩnh trong Tiệm Tích Điểm. "}
TAB_Describe[4555] = {"Không giới hạn"}
TAB_Describe[4556] = {"Ải này chỉ cần ra trận %s anh hùng"}
TAB_Describe[4557] = {"Quy tắc cơ bản"}
TAB_Describe[4558] = {"#C(#40404B)1. Người chơi đạt Lv.#C(#1E90FF)80#C(#40404B) sẽ mở Máy Dẫn Lực, sau khi anh hùng cài đặt Máy Dẫn Lực có thể tăng thuộc tính và dùng ma pháp dẫn lực, anh hùng từ #C(#1E90FF)9 sao trở lên#C(#40404B) được cài đặt Máy Dẫn Lực."}
TAB_Describe[4559] = {"#C(#40404B)2. Mỗi loại Máy Dẫn Lực đều cần tiến hành mở khóa, sau khi mở khóa có thể tiến hành dưỡng, bao gồm: tăng sao đường về, khảm bảo thạch."}
TAB_Describe[4560] = {"Tăng sao đường về"}
TAB_Describe[4561] = {"#C(#40404B)1. Tăng đường về của Máy Dẫn Lực có thể tăng Buff thuộc tính, đồng thời mở khóa có thể dùng cho lỗ Kết Tinh khảm Bảo Thạch."}
TAB_Describe[4562] = {"#C(#40404B)2. Phẩm Máy Dẫn Lực quyết định cấp sao tối đa của đường về, cấp sao càng cao có thể dùng cho càng nhiều Lỗ Kết Tinh khảm Bảo Thạch."}
TAB_Describe[4563] = {"#C(#40404B)3. Nhiều Máy Dẫn Lực chỉ định sẽ có hiệu quả cộng hưởng sau khi nâng cấp đường về đến cấp sao nhất định, buff thuộc tính cho #C(#1E90FF)toàn thể anh hùng#C(#40404B)."}
TAB_Describe[4564] = {"Khảm Bảo Thạch"}
TAB_Describe[4565] = {"#C(#40404B)1. Máy Dẫn Lực khảm Bảo Thạch có thể tăng Buff thuộc tính, tăng #C(#1E90FF)tổng cấp Bảo Thạch#C(#40404B) khảm đạt yêu cầu chỉ định được tăng cấp ma pháp của Máy Dẫn Lực."}
TAB_Describe[4566] = {"#C(#40404B)2. Khảm Bảo Thạch đầu tiên cần#C(#1E90FF)mở khóa Lỗ Kết Tinh#C(#40404B) thông qua nấng cấp đường về, mỗi Lỗ Kết Tinh sẽ giới hạn loại bảo thạch được khảm, chỉ được khảm bảo thạch loại tương ứng."}
TAB_Describe[4567] = {"#C(#40404B)3. Bảo Thạch ban đầu là cấp 1 tối đa cấp 10, cấp càng cao thuộc tính Buff càng nhiều, có thể tiến hành ghép nhiều Bảo Thạch cùng cấp cùng loại đạt được Bảo Thạch cấp cao hơn. "}
TAB_Describe[4568] = {"#C(#40404B)4. Bảo thạch sau khi khảm có thể gỡ hoặc đổi bất kỳ lúc nào, xin lưu ý sau khi gỡ Bảo Thạch sẽ làm giảm tổng cấp Bảo Thạch của Máy Dẫn Lực, nếu không đạt yêu cầu cấp ma pháp dẫn lực của Máy Dẫn Lực cũng sẽ giảm tương ứng."}
TAB_Describe[4569] = {"Xem loại Bảo Thạch"}
TAB_Describe[4570] = {"#C(#40404B)Bảo Thạch Bạo Kích, có thể tăng thuộc tính: Bạo kích, Tăng S.Thương"}
TAB_Describe[4571] = {"#C(#40404B)Bảo Thạch Khống Chế, có thể tăng thuộc tính: Khống Chế, S.Thương vật lý, S.Thương ma pháp"}
TAB_Describe[4572] = {"#C(#40404B)Bảo Thạch Né, có thể tăng thuộc tính: Né, phòng ST khác thường"}
TAB_Describe[4573] = {"#C(#40404B)Bảo Thạch Được Trị Liệu, có thể tăng thuộc tính: Được trị liệu, Miễn giảm S.Thương"}
TAB_Describe[4574] = {"Quy tắc mở"}
TAB_Describe[4575] = {"#C(#40404B)1. Người chơi đạt đến cấp #C(#1E90FF)80#C(#40404B) mở khóa lối chơi Đại hội Đấu Trường."}
TAB_Describe[4576] = {"#C(#40404B)2. Đại hội Đấu Trường mở vào #C(#1E90FF)0:00-23:00 mỗi thứ 2, 4, 6#C(#40404B)."}
TAB_Describe[4577] = {"Quy tắc khiêu chiến"}
TAB_Describe[4578] = {"#C(#40404B)1. Mỗi lần tham gia Đại hội Đấu Trường hệ thống sẽ dựa vào lực chiến của người chơi để tiến hành bắt cặp và phân phối đến 20 đối thủ, người chơi mỗi lần khiêu chiến đều sẽ chiến đấu với 20 đối thủ ngẫu nhiên chưa từng khiêu chiến này."}
TAB_Describe[4579] = {"#C(#40404B)2. Mỗi lần khiêu chiến thắng lợi số trận thắng liên tục +1 có thể tiếp tục tiến hành khiêu chiến, số trận thắng liên tục càng nhiều thưởng càng hậu hĩnh, nếu khiêu chiến thất bại thì bắt cặp lần này kết thúc cần tiến hành bắt cặp lại. "}
TAB_Describe[4580] = {"#C(#40404B)3. Tiến hành bắt cặp cần tốn số lần, ban đầu nhận 1 lần, đạt VIP5 nhận thêm 1 lần, trong quá trình Đại hội Đấu Trường nếu chiến đấu #C(#1E90FF)3 trận đầu tiên(#40404B) thất bại sẽ hoàn trả 1 lần."}
TAB_Describe[4581] = {"#C(#40404B)4. Khi khiêu chiến thắng lợi sẽ tăng #C(#1E90FF)điểm mệt mỏi#C(#40404B), lượt chiến đấu càng dài, điểm mệt mỏi càng nhiều, điểm mệt mỏi sẽ #C(#1E90FF)suy yếu#C(#40404B) thuộc tính của tất cả anh hùng tham gia chiến đấu. "}
TAB_Describe[4582] = {"#C(#40404B)5. Điểm mệt mỏi sẽ xóa sạch khi tiến hành bắt cặp lại. "}
TAB_Describe[4583] = {"Quy tắc thưởng"}
TAB_Describe[4584] = {"#C(#40404B)1. Thưởng thắng liên tục: Số trận thắng liên tục càng nhiều thưởng nhận được càng cao, thưởng tự động phát khi giành được nhiều nhất 20 lần thắng liên tục hoặc khiêu chiến thất bại, nếu thời gian khiêu chiến kết thúc sẽ dựa vào số trận thắng liên tục đã có được hiện tại để phát thưởng qua thư. "}
TAB_Describe[4585] = {"#C(#40404B)2. Nhiệm vụ tích lũy trận thắng mỗi tuần: Thứ 2 đến chủ nhật mỗi tuần tham gia Đại hội Đấu Trường có thể tích lũy số trận thắng, đạt yêu cầu nhiệm vụ được nhận thưởng, 0:00 mỗi thứ 2 cài lại nhiệm vụ."}
TAB_Describe[4586] = {"Xác nhận"}
TAB_Describe[4587] = {"×%s/%s"}
TAB_Describe[4588] = {"Hôm nay là ngày thi đấu cuối cùng\n23:00 tổng kết xếp hạng cuối cùng\n(TOP 32 người chơi sẽ vào Giải Vương Giả)"}
