TAB_Describe[4590] = {"Thứ 6 tuần sau mở báo danh sự kiện lần nữa"}
TAB_Describe[4591] = {"Nhanh ra đây Kujo Jotaro, ta nhìn thấy rồi!"}
TAB_Describe[4592] = {"Ngươi gọi Kujo Jotaro cùng lên nào."}
TAB_Describe[4593] = {"Đánh đổ ngươi và Kujo Jotaro, cơ bản chưa đến 1 giây"}
TAB_Describe[4594] = {"Kujo Jotaro, bỏ mạng tiếp theo là ngươi rồi"}
TAB_Describe[4595] = {"Ngươi xác định muốn về phía Kujo Jotaro, đối đầu với ta?"}
TAB_Describe[4596] = {"Mùi vị khiến người ta hăng hái, Kujo Jotaro là ngươi sao?"}
