TAB_Describe[4611] = {"Bỏ trống %s vòng trước thi đấu lần này"}
TAB_Describe[4612] = {"Chúc phúc và mở khóa"}
TAB_Describe[4613] = {"#C(#40404B)1. Cấp người chơi đạt #C(#1E90FF)90#C(#40404B) mở tính năng Giải phong ấn và chúc phúc Thần Khí."}
TAB_Describe[4614] = {"#C(#40404B)2. Tăng cấp chúc phúc Thần Khí có thể tăng thêm Buff thuộc tính của toàn thể anh hùng, đồng thời tăng sát thương kỹ năng Thần Khí. Cấp chúc phúc quyết định tỷ lệ % sát thương tăng thêm, lấy lực công của anh hùng #C(#1E90FF)lực chiến thấp nhất#C(#40404B) trong anh hùng ra trận tiến hành chuyển đổi."}
TAB_Describe[4615] = {"#C(#40404B)3. Sau khi tiến hành giải phong ấn Thần Khí, khi Thần Khí đang thi triển kỹ năng có xác suất nhất định tấn công thêm #C(#1E90FF)1#C(#40404B) mục tiêu."}
TAB_Describe[4616] = {"#C(#40404B)4. Thần Khí cần lần đầu tiến hành giải phong ấn mới được chúc phúc, số lần giải phong ấn quyết định giới hạn cấp chúc phúc."}
TAB_Describe[4617] = {"Điện Anh Linh"}
TAB_Describe[4618] = {"Phạm vi thuộc tính ngẫu nhiên: "}
TAB_Describe[4619] = {"#C(#40404B)1. Người chơi đạt Lv.#C(#1E90FF)90#C(#40404B) sẽ mở khóa Aincrad, mở vào #C(#1E90FF)thứ 3, 5, 7, cả ngày chủ nhật#C(#40404B) mỗi tuần."}
TAB_Describe[4620] = {"#C(#40404B)2. Ain Grande có 100 tầng, mỗi tầng cố định 10 ải có thể tiến hành khiêu chiến, khi khiêu chiến số lượng anh hùng ra trận cần #C(#1E90FF)≥5#C(#40404B) người, kết thúc chiến đấu số lượng anh hùng sống sót cũng phải #C(#1E90FF)≥5#C(#40404B) người  mới được vượt ải."}
TAB_Describe[4621] = {"#C(#40404B)3. Khi tiến hành khiêu chiến tính toán số anh hùng ra trận, anh hùng viện quân không tính vào, khi kết thúc chiến đấu tính toán số lượng anh hùng còn sống, anh hùng viện quân #C(#1E90FF)nếu đã xuất chiến#C(#40404B) thì sẽ tính vào."}
TAB_Describe[4622] = {"#C(#40404B)4. Một số ải sẽ có #C(#1E90FF)nhiều đội#C(#40404B) quân địch, lần lượt đánh bại hết #C(#1E90FF)tất cả#C(#40404B) mới được vượt ải."}
TAB_Describe[4623] = {"#C(#40404B)5. Người chơi tham gia lần đầu bắt đầu công lược từ tầng 1, vượt tất cả ải và khi mở lần sau lực chiến đạt yêu cầu chỉ định có thể khiêu chiến tầng sau, nếu không số tầng không thay đổi. Sau khi vượt ải tầng cao nhất sẽ không thay đổi."}
TAB_Describe[4624] = {"#C(#40404B)6. Mỗi tầng đều có 3 thưởng rương, số lượng vượt ải đạt yêu cầu có thể nhận, nhận lần đầu được thưởng lớn, khiêu chiến lặp lại thưởng nhận sẽ giảm."}
TAB_Describe[4625] = {"#C(#2B2B34)Bạn đã nhận được tiếp ứng này, tiếp tục dùng sẽ tự động phân tách thành #I(T0)res/icon/ItemSmall/itemsmall_%s.png#C(#00861c)%s#C(#2B2B34), có thể đổi vật phẩm khác trong sự kiện tiếp ứng."}
TAB_Describe[4626] = {"Hoàn thành khiêu chiến, đấu giá đúng 20:00 mở, có thể đấu giá vật phẩm quý hiếm và tham gia chia hoa hồng Guild, nhớ đừng bỏ lỡ."}
